import React from "react"
import type { ReactNode } from "react"
import { cn } from "@heroui/react"
import { Button } from "@sb-components/atoms/buttons/Button/Button"
import {
    ButtonGroupRoot,
    ButtonGroupSeparator,
} from "@sb-components/atoms/buttons/ButtonGroup/ButtonGroup"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * `Button.RadioGroup` ΓÇö a flex-wrap row of selectable buttons, single- or multi-select.
 * Leaves: `items` builds N child buttons (`Default`, with per-item `isDisabled`); `multiple`
 * allows ΓëÑ2 selected at once; `trailing` appends a non-option button (e.g. "+N"); `itemAction`
 * turns each item into a fused `ButtonGroup` [select | delete | more].
 */

interface CloneableActionElementProps {
    children?: ReactNode
}

/** One selectable button in a {@link ButtonRadioGroup}. */
export interface ButtonRadioGroupItem<T extends string> {
    /** Value selected when this button is chosen. */
    value: T
    /** Button content (icon + label + meta ΓÇö caller-defined inline row). */
    content: ReactNode
    /** When true the button is dimmed and not selectable. */
    isDisabled?: boolean
}

/** Props shared by both the single- and multi-select modes of {@link ButtonRadioGroup}. */
interface ButtonRadioGroupBaseProps<T extends string> {
    /** The selectable buttons. */
    items: Array<ButtonRadioGroupItem<T>>
    /** Accessible label for the group. */
    ariaLabel: string
    /**
     * Optional trailing node placed after the buttons in the SAME row (e.g. a
     * "+N" overflow button). Not part of the group's value ΓÇö it's an action.
     */
    trailing?: ReactNode
    /**
     * Optional per-item trailing action(s) ΓÇö e.g. a delete button and/or a "Γï«"
     * (kebab) menu trigger. When provided, the item's select button and these
     * action buttons render as ONE connected `ButtonGroup` per item
     * (`[select | delete | Γï«]`). Return the action `<Button>`s as an ARRAY (with
     * `key`s) so each is an individual segment. Omit for a plain single-select row.
     */
    itemAction?: (item: ButtonRadioGroupItem<T>) => ReactNode
    /**
     * Where this sits inside its parent. Appearance is not passable ΓÇö it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/** Single-select mode (default) ΓÇö exactly one value selected at a time. */
interface ButtonRadioGroupSingleProps<T extends string> extends ButtonRadioGroupBaseProps<T> {
    /** Single-select ΓÇö omit or pass `false`. */
    multiple?: false
    /** Currently selected value. */
    value: T
    /** Fired with the chosen value when a button is selected. */
    onChange: (value: T) => void
}

/**
 * Multi-select mode ΓÇö a SET of values, each button an independent toggle. The
 * caller owns the set + the toggle logic (e.g. enforcing "at least one selected");
 * this component only reports which button was pressed via {@link onToggle}.
 */
interface ButtonRadioGroupMultiProps<T extends string> extends ButtonRadioGroupBaseProps<T> {
    /** Multi-select ΓÇö pass `true`. */
    multiple: true
    /** Currently selected values. */
    values: Array<T>
    /** Fired with the pressed value (the caller adds/removes it from its own set). */
    onToggle: (value: T) => void
}

/** Props for {@link ButtonRadioGroup} ΓÇö a discriminated union on `multiple`. */
export type ButtonRadioGroupProps<T extends string> =
    | ButtonRadioGroupSingleProps<T>
    | ButtonRadioGroupMultiProps<T>

/** Source-level tier metadata ΓÇö see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "ButtonRadioGroup" } as const

/**
 * A single-select toggle-button group laid out as a flex-wrap row (buttons wrap
 * to the next line, never scroll). Every option is a house `<Button>`:
 * standalone, selected = filled `tertiary` (NEUTRAL, not accent ΓÇö a facet/config
 * toggle isn't a CTA), unselected = hollow `ghost`. NEVER `primary` here ΓÇö a config
 * row commonly sits on the SAME surface as the page's one accent CTA.
 *
 * When `itemAction` is supplied, each item instead renders as one connected
 * `ButtonGroup` ΓÇö the select button + its action button(s) touching, only the
 * two outer ends rounded (`[select | delete | Γï«]`). The seam is the house
 * `ButtonGroupSeparator`, baked to the `--border` token and full-height.
 *
 * `role="group"` + `aria-pressed` per option ΓÇö works for BOTH the default
 * single-select toggle group and the multi-select mode. House `Button` does not
 * accept `aria-pressed`, so the standalone path wraps the control in a span;
 * the fused `ButtonGroupRoot` path cannot wrap (segments must be buttons), so
 * pressed state is carried only on the standalone span.
 *
 * @param props - {@link ButtonRadioGroupProps}
 */
export const ButtonRadioGroup = <T extends string>(props: ButtonRadioGroupProps<T>) => {
    const { items, ariaLabel, trailing, itemAction, classNames } = props
    // narrow the discriminated union once ΓÇö selection state + the press handler are
    // the only things that differ between single- and multi-select.
    const isSelected = (candidate: T): boolean =>
        (props.multiple ? props.values.includes(candidate) : props.value === candidate)
    const handlePress = (candidate: T): void => {
        if (props.multiple) {
            props.onToggle(candidate)
        } else {
            props.onChange(candidate)
        }
    }
    return (
        <div
            role="group"
            aria-label={ariaLabel}
            className={cn("flex flex-wrap items-center gap-2", classNames)}
            data-tier="composite"
            data-component="ButtonRadioGroup"
            data-principle="flex-action"
        >
            {items.map((item) => {
                const selected = isSelected(item.value)
                if (!itemAction) {
                    // standalone: selected = filled `tertiary`, unselected = hollow `ghost`.
                    return (
                        <span key={item.value} aria-pressed={selected}>
                            <Button
                                size="sm"
                                variant={selected ? "tertiary" : "ghost"}
                                isDisabled={item.isDisabled}
                                onPress={() => handlePress(item.value)}
                                label={item.content}
                            />
                        </span>
                    )
                }
                // select button + its action(s) = one connected ButtonGroup per item.
                // Each action button gets a `ButtonGroupSeparator` injected at the head
                // of its children ΓÇö the separator must sit inside the following button.
                return (
                    <ButtonGroupRoot key={item.value} size="sm">
                        <Button
                            size="sm"
                            variant={selected ? "secondary" : "tertiary"}
                            isDisabled={item.isDisabled}
                            onPress={() => handlePress(item.value)}
                            label={item.content}
                        />
                        {React.Children.map(itemAction(item), (action) =>
                            React.isValidElement<CloneableActionElementProps>(action)
                                ? React.cloneElement(
                                    action,
                                    undefined,
                                    <ButtonGroupSeparator />,
                                    action.props.children,
                                )
                                : action,
                        )}
                    </ButtonGroupRoot>
                )
            })}
            {trailing}
        </div>
    )
}

import { cn } from "@heroui/react"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import { Divider } from "@sb-components/atoms/display/Divider/Divider"
import { SnippetIcon } from "@sb-components/atoms/display/SnippetIcon/SnippetIcon"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"
import { GAP_CLASS, type AllowedGap } from "@sb-components/frames/_spacing"

/**
 * `KeyValue.*` ΓÇö the labelΓÇôvalue pair composite, for spec tables, order summaries,
 * and invoices where "one name, one number" repeats.
 *
 * | Member | Shape | Content channel |
 * |---|---|---|
 * | `.Row`  | ONE labelΓÇôvalue pair | data props (`label`/`value`/`hint`) |
 * | `.List` | N pairs stacked vertically | `items` DATA ΓÇö children forbidden |
 *
 * The composite carries no domain content and does NOT format money/dates/units ΓÇö
 * the consumer passes an already-formatted `string` into `value` (`"1,200,000 Γé½"`).
 * `label`/`value` are `string`, never `ReactNode`; the row wraps each in
 * `Typography` itself, which is what lets it shimmer either one while `isSkeleton`.
 * `emphasis` is a visual stress for a total row only ΓÇö the number is still supplied
 * by the consumer (no self-computed totals). Text goes through `Typography.*`,
 * rules through `Divider`. The gap scale is enforced by type ({@link AllowedGap},
 * `1..8`).
 */


/** Source-level tier metadata ΓÇö see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "KeyValue" } as const

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// .Row ΓÇö ONE labelΓÇôvalue pair
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/** Props every {@link KeyValueRow} carries regardless of loading state. */
interface KeyValueRowOwnProps {
    /**
     * Sub-line below the label (explanation/unit/condition) ΓÇö muted, smaller size.
     * A plain `string`: the row wraps it in `Typography` itself (COMPOSITE-8) ΓÇö a
     * built node here would already be called and unable to shimmer.
     */
    hint?: string
    /** `true` ΓåÆ a TOTAL row: label goes to foreground medium, value goes to base size + bold. */
    emphasis?: boolean
    /** `true` ΓåÆ draws a SEPARATOR line below the row (seam between this row and the next). */
    divider?: boolean
    /** Gap between the row's content and the `divider` line (┬º10). Default `4` (`gap-3`). */
    gap?: AllowedGap
    /**
     * `true` ΓåÆ renders a one-tap {@link SnippetIcon} copy affordance beside the
     * value, copying the row's `value` string to the clipboard. Additive:
     * default `false`, so an existing row with no `copyable` renders exactly as
     * before. The affordance is skipped entirely while `isSkeleton` ΓÇö there is
     * nothing real yet to copy, so the row decides not to draw it rather than
     * shimmer a control with no value behind it (COMPOSITE-10).
     */
    copyable?: boolean
    /**
     * Anatomy tag for THIS composite itself ΓÇö lets the PARENT badge it as ONE node (┬º11a.1).
     * Without this prop the composite doesn't make it into the Deps tree: using a
     * `frame`/`composite` tier node that the panel can't see counts as not using it.
     */
    /**
     * Where this sits inside its parent. Appearance is not passable ΓÇö it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * Props for {@link KeyValueRow}. `label`/`value` are REQUIRED unless `isSkeleton`
 * (┬º12b) ΓÇö a shimmer row has no real pair to show yet.
 */
export type KeyValueRowProps = KeyValueRowOwnProps &
    (
        | { isSkeleton: true; label?: string; value?: string }
        | { isSkeleton?: false; label: string; value: string }
    )

/**
 * One labelΓÇôvalue row: label (+`hint`) sits left, value sits right, `tabular-nums`
 * keeps the digits aligned in a column when rows stack (┬º3). `emphasis` is the
 * STRESS level for a total row.
 *
 * @param props - {@link KeyValueRowProps}
 */
const KeyValueRow = ({
    label,
    value,
    hint,
    emphasis = false,
    divider = false,
    gap = 4,
    copyable = false,
    isSkeleton = false,
    classNames,
}: KeyValueRowProps) => {
    // COMPOSITE-10: ONE render path ΓÇö same two-column `StackH`, same label+hint
    // `StackV` cluster, in both states. Every piece of text goes through
    // `Typography`'s own `isSkeleton` (┬º12c: the atom draws its own bar, sized to
    // its own value) ΓÇö there is no second, hand-built skeleton pair to keep in
    // sync with this one.
    // Label column: label + hint form a TIGHT cluster (┬º10b `tight` = gap-1) ΓÇö the
    // same "a label continuing into its hint" shape the registry names `title-subtitle`.
    const pairContent = (
        <>
            <StackV
                gap={2}
                classNames={["min-w-0"]}
                principle="title-subtitle"
                explain="Title over supporting line ΓÇö not label-field, because neither line is a form control label."
                isSkeleton={isSkeleton}
                items={[
                    () => (
                        <span>
                            <Typography size="sm"
                                text={label}
                                color={isSkeleton ? undefined : (emphasis ? undefined : "muted")}
                                weight={isSkeleton ? undefined : (emphasis ? "medium" : undefined)}
                                isSkeleton={isSkeleton}
                            />
                        </span>
                    ),
                    ...(hint != null ? [() => (
                        <span>
                            <Typography size="xs"
                                text={hint}
                                color={isSkeleton ? undefined : "muted"}
                                isSkeleton={isSkeleton}
                            />
                        </span>
                    )] : []),
                ]}
            />
            <span
                className={cn("flex shrink-0 items-center", copyable && !isSkeleton && "gap-2")}
                data-principle={copyable && !isSkeleton ? "flex-action" : undefined}
            >
                <span>
                    {emphasis ? (
                        <Typography text={value} weight={isSkeleton ? undefined : "bold"} tabularNums={!isSkeleton} isSkeleton={isSkeleton} />
                    ) : (
                        <Typography size="sm" text={value} weight={isSkeleton ? undefined : "medium"} tabularNums={!isSkeleton} isSkeleton={isSkeleton} />
                    )}
                </span>
                {copyable && !isSkeleton ? (
                    <span>
                        {/* `value` is guaranteed a real string whenever `!isSkeleton` (the
                            discriminated union above) ΓÇö the `?? ""` only satisfies narrowing
                            across the destructure and is never seen. */}
                        <SnippetIcon copyString={value ?? ""} />
                    </span>
                ) : null}
            </span>
        </>
    )
    const row = (
        <StackH
            align="start"
            justify="between"
            gap={3}
            principle="value-row"
            explain="Holds a label and its numeric value on one baseline so the count stays readable against the label."
            classNames={classNames}
            isSkeleton={isSkeleton}
            items={[() => pairContent]}
        />
    )
    if (!divider) {
        return row
    }
    return (
        <div className={cn("flex flex-col", GAP_CLASS[gap])}>
            {row}
            <span className="block">
                <Divider variant="tertiary" />
            </span>
        </div>
    )
}

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// .List ΓÇö N pairs stacked vertically (repeated list ΓçÆ items)
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/** ONE row in {@link KeyValueList} ΓÇö described as DATA, not JSX. */
export interface KeyValueListItem {
    /** React key. */
    key: string
    /** Label (left side). `string` ΓÇö the row wraps it in `Typography` itself. */
    label: string
    /** Value (right side) ΓÇö an already-formatted `string` (COMPOSITE-8). */
    value: string
    /** Sub-line below the label. Plain `string` ΓÇö see {@link KeyValueRowOwnProps.hint}. */
    hint?: string
    /** `true` ΓåÆ a TOTAL row (visual emphasis). */
    emphasis?: boolean
    /** `true` ΓåÆ this row gets the {@link KeyValueRowOwnProps.copyable} copy affordance. */
    copyable?: boolean
}

/** Props for {@link KeyValueList}. */
export interface KeyValueListProps {
    /** The rows, in reading order. REQUIRED ΓÇö a repeated list = data (┬º13b). */
    items: ReadonlyArray<KeyValueListItem>
    /** Gap between rows, ENFORCED by the ┬º10 scale. Default `4` (`gap-3`, vertical rows). */
    gap?: AllowedGap
    /** `true` ΓåÆ draws a separator line BETWEEN rows (the last row has none). */
    divider?: boolean
    /**
     * `true` ΓåÆ render `skeletonRows` placeholder rows instead of `items` (same
     * contract as `List.Labeled`'s own `isSkeleton`/`skeletonRows` pair).
     */
    isSkeleton?: boolean
    /** Placeholder row count while `isSkeleton`. Defaults to `3`. */
    skeletonRows?: number
    /**
     * Anatomy tag for THIS composite itself ΓÇö lets the PARENT badge it as ONE node (┬º11a.1).
     * Without this prop the composite doesn't make it into the Deps tree: using a
     * `frame`/`composite` tier node that the panel can't see counts as not using it.
     */
    /**
     * Where this sits inside its parent. Appearance is not passable ΓÇö it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * A column of {@link KeyValueRow} rows built from `items`. The separator line (if
 * enabled) is decided by the LIST ΓÇö the LAST row has none, so the seam always sits
 * BETWEEN two rows instead of leaving a stray line dangling at the bottom. The gap
 * around each row-and-line shares the list's `gap` ΓçÆ the rhythm above/below the line
 * is always even (┬º10a: one seam, one owner).
 *
 * @param props - {@link KeyValueListProps}
 */
const KeyValueList = ({
    items,
    gap = 4,
    divider = false,
    isSkeleton = false,
    skeletonRows = 3,
    classNames,
}: KeyValueListProps) => (
    <div

        className={cn("flex flex-col", GAP_CLASS[gap], classNames)}
        data-tier="composite"
        data-component="KeyValueList"
    >
        {isSkeleton
            ? Array.from({ length: skeletonRows }, (_unused, index) => (
                <KeyValueRow key={index} isSkeleton divider={divider && index < skeletonRows - 1} gap={gap} />
            ))
            : items.map(({ key, ...item }, index) => (
                <KeyValueRow
                    key={key}
                    {...item}
                    divider={divider && index < items.length - 1}
                    gap={gap}

                />
            ))}
    </div>
)

/**
 * `KeyValue.*` ΓÇö the labelΓÇôvalue pair composite (COMPOSITE tier ┬º13). `Row` (one pair) ┬╖
 * `List` (N pairs, `items`). Visual variants = PROP (`emphasis`/`divider`), ┬º6b.
 */
export { KeyValueRow, KeyValueList }

/** Folder-matching compound namespace (export-matches-folder / ATOM-11 sync). */
export const KeyValue = {
    Row: KeyValueRow,
    List: KeyValueList,
} as const

import type { ReactNode } from "react"
import { Label, Skeleton as HeroSkeleton, cn } from "@heroui/react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * `FieldFrame` ΓÇö the label / hint / control / error scaffold every form atom
 * composes so the atom itself is the full field.
 *
 * Composite form helper: label / hint / control / error scaffold.
 * Owns the vertical rhythm (`flex flex-col`, a fixed `gap-3` ΓÇö the label rule,
 * see `FIELD_SEAM`): label on top, hint below the label, control, error line
 * last ΓÇö and mirrors the exact shape when `isSkeleton`.
 *
 * "Bare" mode: when there is no label/hint/errorMessage/required (and not
 * skeleton), FieldFrame renders `children` directly with zero wrapper, so the
 * atom can still be used as a bare cell nested inside something else.
 */
export interface FieldFrameProps {
    /** Label above the control (`text-sm font-medium`). Omit ΓåÆ no label. */
    label?: ReactNode
    /** Description below the label (`text-xs text-muted`) ΓÇö ALWAYS shown (unlike errorMessage). */
    hint?: ReactNode
    /** Error line below the control (`text-sm text-danger`) ΓÇö set ΓåÆ field invalid. */
    errorMessage?: ReactNode
    /** Adds a `*` mark (text-danger) after the label. */
    isRequired?: boolean
    /** Dims the label (locking the control itself is the atom's job). */
    isDisabled?: boolean
    /** Loading mirror: a label-width skeleton over a control-skeleton, keeping the same column. */
    isSkeleton?: boolean
    /** Control-shaped skeleton for `isSkeleton` (the atom passes its own box). */
    skeletonControl?: ReactNode
    /**
     * The real control (an already-wrapped HeroUI cell). `FieldFrame` is a
     * wrapping frame that must accept the calling atom's arbitrary control
     * as-is (Input/Select/Choice/ΓÇª) ΓÇö it can't be swapped for a data prop,
     * since the control isn't "content" but a whole component tree.
     */
    children?: ReactNode
    /** The control's `id` so the label's `htmlFor` points correctly ΓÇö the atom passes the same id down to the control. */
    id?: string
    /** Where this sits inside its parent (the outer column). Everything about appearance is a prop of its own. */
    classNames?: Array<AllowedClassName>
}

/**
 * Accessible NAME for the control: when `label` is a string, use it directly
 * (guarantees the control always has a readable name ΓÇö even a compound control
 * like Number/Date/Otp that can't wire up `htmlFor`), otherwise falls back to
 * `fallback` (ariaLabel/placeholder). Avoids the a11y gap of an "unnamed control"
 * when a field has a label that can't be associated.
 */
export const fieldName = (label: ReactNode, fallback?: string): string | undefined =>
    typeof label === "string" ? label : fallback

/**
 * The seam between a label and the control it names is step 4 (`gap-3`, 12px) ΓÇö a label names its
 * subject across a change of register, and `principles/gap.md`'s label rule sits that boundary at
 * step 4. It is fixed, not a prop: the old `tight`/`related` choice let one field breathe at a
 * different rhythm than the next for no reason a reader could name, which is the ambiguity the
 * numeric scale exists to end. Every field in the system now stacks at the same seam.
 */
const FIELD_SEAM = "gap-3"

/** Label + `*` mark when required. */
const withRequired = (label: ReactNode, isRequired?: boolean) =>
    isRequired ? (
        <>
            {label} <span className="text-danger">*</span>
        </>
    ) : (
        label
    )

/**
 * `FieldFrame` ΓÇö label/hint/control/error column shared by every form atom.
 * @param props - {@link FieldFrameProps}
 */
const FieldFrameBase = ({
    label,
    hint,
    errorMessage,
    isRequired,
    isDisabled,
    isSkeleton,
    skeletonControl,
    children,
    id,
    classNames,
}: FieldFrameProps) => {
    const hasFrame = label != null || hint != null || errorMessage != null

    // ΓöÇΓöÇ Loading mirror ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    if (isSkeleton) {
        // Bare skeleton (no label frame) ΓåÆ just the control skeleton box (badges Skeleton itself).
        if (!hasFrame && label == null) {
            return <>{skeletonControl}</>
        }
        return (
            <div data-tier="composite" data-component="FieldFrame" data-principle="label-field" className={cn("flex flex-col", FIELD_SEAM, classNames)}>
                {label != null ? (
                    // label-bar look), not the slot word "Label" it stands in for.
                    <HeroSkeleton className="h-4 w-1/3 rounded-md" />
                ) : null}
                {skeletonControl}
            </div>
        )
    }

    // ΓöÇΓöÇ "Bare" ΓÇö no frame ΓåÆ renders the control directly ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    if (!hasFrame) {
        return <>{children}</>
    }

    // ΓöÇΓöÇ Full field ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    return (
        <div data-tier="composite" data-component="FieldFrame" className={cn("flex flex-col", FIELD_SEAM, classNames)}>
            {label != null ? (
                <Label htmlFor={id} isDisabled={isDisabled} className="text-sm font-medium">
                    {withRequired(label, isRequired)}
                </Label>
            ) : null}

            {hint != null ? (
                <p className="text-muted text-xs">
                    {hint}
                </p>
            ) : null}

            {children}

            {errorMessage != null ? (
                <p className="text-danger text-sm">
                    {errorMessage}
                </p>
            ) : null}
        </div>
    )
}

/** `FieldFrame` ΓÇö label/hint/control/error scaffold. */
export { FieldFrameBase as FieldFrame }

export const meta = { tier: "composite", name: "FieldFrame" } as const

import React from "react"
import { cn } from "@heroui/react"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"
import { Chip } from "@sb-components/atoms/chips/Chip/Chip"
import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import type { ComponentTypeWithSkeleton } from "@sb-components/frames/_slot"
import { StackH, StackV } from "@sb-components/frames/Stack/Stack"

/**
 * `Page.*` ΓÇö the page-chrome frame namespace: the chrome of a ROUTE (what sits
 * above the content and pinned under it). Members are `PageHeader` and
 * `PageBottomBar`.
 *
 * `PageBottomBar` is a wrapper frame with named slots `body`/`actions`. `PageHeader` is not a generic wrapper ΓÇö it owns semantic
 * slots (`breadcrumb`/`title`/`description`/`actions`/`meta`) and takes no
 * `children`. No repeating list, so no `items` member. Namespace only ΓÇö no bare
 * component export.
 *
 * Both members own their own `isSkeleton`, so every slot they render is a component
 * reference (`ComponentType<{ isSkeleton?: boolean }>`) the frame calls itself to
 * forward the flag; text the frame renders directly through `Typography`
 * (`title`/`description`) is a plain `string`.
 */

/** Source-level tier metadata ΓÇö see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "Page" } as const

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// .Header ΓÇö the breadcrumb/title/description/actions/meta block (was `PageHeader`)
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/** Props {@link PageHeader} carries regardless of loading state. */
interface PageHeaderOwnProps {
    /**
     * Optional supporting description placed directly below the title. The
     * frame renders it through `Typography` itself (`text-sm`, muted tone) and
     * forwards `isSkeleton`, so this is plain text (COMPOSITE-8), not a
     * pre-built node. Omit when the title is self-explanatory.
     */
    description?: string
    /**
     * Optional breadcrumb row rendered above the title row, as a COMPONENT
     * reference (COMPOSITE-8) ΓÇö the frame calls it itself. Typically a
     * `<Breadcrumbs>` house atom or a `LinkBack`. Omitted entirely while
     * loading (a route rarely needs it before data lands).
     */
    breadcrumb?: ComponentTypeWithSkeleton
    /**
     * Optional right-aligned slot for action controls, as a COMPONENT
     * reference ΓÇö the frame calls it and renders it `shrink-0` so it never
     * compresses the title column. Omitted entirely while loading.
     */
    actions?: ComponentTypeWithSkeleton
    /**
     * Optional meta row placed BELOW the title/description ΓÇö typically a row
     * of stat/meta chips ("24 Modules ┬╖ 87 Content items ΓÇª") ΓÇö as a
     * COMPONENT reference. Rendered `gap-3` from the title block. While
     * loading, the frame draws its OWN 2-chip placeholder instead of calling
     * this (COMPOSITE-10: the frame decides how many, not this slot). Omit
     * when the header carries no stats.
     */
    meta?: ComponentTypeWithSkeleton
    /**
     * Title scale. `"page"` (default) = `Typography.Heading` level 3 ΓÇö a route's
     * OWN page title. `"compact"` = body-size bold, for a header that labels a
     * PANE/PHASE inside an existing page shell.
     */
    size?: "page" | "compact"
    /**
     * Where this sits inside its parent. Appearance is not passable ΓÇö it is already a prop.
     */
    classNames?: Array<AllowedClassName>
    /**
     * `true` ΓåÆ each part this frame renders carries a ``
     * attribute so a BlockAnatomy panel can badge it on-render. Off in production.
     */
}

/**
 * Props for {@link PageHeader}. `title` is REQUIRED unless `isSkeleton` (┬º12b) ΓÇö
 * a shimmer header has no real title to show yet.
 */
export type PageHeaderProps = PageHeaderOwnProps &
    (
        | {
            isSkeleton: true
            /** Primary page or section title. See the live variant's doc for the full contract. */
            title?: string
        }
        | {
            isSkeleton?: false
            /**
             * Primary page or section title. Rendered at `text-xl font-medium` in the
             * foreground tone through `Typography` (COMPOSITE-8: the frame builds it
             * itself, so this is plain text).
             */
            title: string
        }
    )

/**
 * Page/section header frame. Renders an optional breadcrumb row above a flex
 * row that places a stacked title + description on the left and optional action
 * controls on the right.
 *
 * This frame carries no card wrapper ΓÇö the caller places it directly inside
 * a `Container` or wraps it in a `SectionCard` when a framed surface
 * is required.
 *
 * @param props - See {@link PageHeaderProps}.
 */
const Header = ({
    title,
    description,
    breadcrumb: Breadcrumb,
    actions: Actions,
    meta: Meta,
    size = "page",
    isSkeleton = false,
    classNames,
}: PageHeaderProps) => {
    // ONE render path (┬º12c) ΓÇö every part this frame would render anyway stays,
    // each handed `isSkeleton`; the atoms draw their own shimmer. While loading, the
    // real shape (breadcrumb/description/meta presence) isn't known yet, so the
    // composite makes the same shape call the old hand-split branch made: assume a
    // description line and a 2-chip meta row, skip breadcrumb/actions (a route
    // rarely needs those before data lands).
    const showDescription = isSkeleton || description != null
    const showMeta = isSkeleton || Meta != null

    // Left column: stacked title and optional description
    const titleBlock = (
        <>
            {size === "compact" ? (
                <Typography weight="bold" isSkeleton={isSkeleton} text={title} />
            ) : (
                <Typography size="h3" weight="bold" isSkeleton={isSkeleton} text={title} />
            )}
            {showDescription ? (
                // clamp to 2 lines on mobile (keep the header short on a phone); full on sm+
                // ΓÇö a viewport-width decision, so the wrapper owns it, not the atom.
                <div className={isSkeleton ? undefined : "line-clamp-2 @app-sm:line-clamp-none"}>
                    <Typography
                        size="sm"
                        color="muted"
                        isSkeleton={isSkeleton}
                        text={description}
                    />
                </div>
            ) : null}
        </>
    )
    // Main row: title+description stack on the left, actions pinned to the right
    const titleRow = (
        <StackH
            align="start"
            justify="between"
            gap={4}
            principle="content-row"
            isSkeleton={isSkeleton}
            items={[
                () => <StackV gap={3} classNames={["min-w-0"]} isSkeleton={isSkeleton} items={[() => titleBlock]} />,
                // Right slot: shrink-0 prevents action buttons from being squeezed.
                // Omitted while loading ΓÇö the shape of the action row isn't known yet.
                ...(!isSkeleton && Actions ? [() => (
                    <div className="shrink-0"><Actions isSkeleton={isSkeleton} /></div>
                )] : []),
            ]}
        />
    )
    const headerBody = (
        <>
            {/* Breadcrumb row ΓÇö rendered only when provided and loaded, sits above the main title row */}
            {!isSkeleton && Breadcrumb ? (
                <div><Breadcrumb isSkeleton={isSkeleton} /></div>
            ) : null}
            {titleRow}
            {/* Meta row: stat/meta chips below the title block (gap={4} from outer). While
                loading, 2 `Chip` placeholders stand in ΓÇö the composite decides the count,
                the atom draws its own pill shimmer (no hand-rolled bar). */}
            {showMeta ? (
                isSkeleton ? (
                    <StackH
                        gap={3}
                        align="stretch"
                        principle="chip-row"
                        explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                        isSkeleton={isSkeleton}
                        items={[
                            () => <Chip isSkeleton />,
                            () => <Chip isSkeleton />,
                        ]}
                    />
                ) : (
                    <div>{Meta ? <Meta isSkeleton={isSkeleton} /> : null}</div>
                )
            ) : null}
        </>
    )
    return (
        // outer gap={4}: breadcrumb Γåö title-block Γåö meta (different header tiers);
        // title Γåö description stay a related gap={3} pair inside the title block.
        <StackV gap={4} classNames={classNames} isSkeleton={isSkeleton} items={[() => headerBody]} />
    )
}

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// .BottomBar ΓÇö the viewport-pinned action bar (was `StickyBottomBar`)
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/** Props for {@link PageBottomBar}. */
export interface PageBottomBarProps {
    /**
     * Leading content of the bar ΓÇö typically a price ΓÇö as a COMPONENT
     * reference (COMPOSITE-8): the frame calls it itself so it can forward
     * `isSkeleton`.
     */
    body?: ComponentTypeWithSkeleton
    /**
     * Trailing control(s) ΓÇö the primary CTA ΓÇö as a COMPONENT reference. When
     * BOTH `body` and `actions` are given the frame lays out the row itself
     * (`justify-between`, `shrink-0` on the actions) so callers stop
     * hand-rolling that flex row.
     */
    actions?: ComponentTypeWithSkeleton
    /** Shorthand for {@link PageBottomBarProps.body} ΓÇö same component-reference contract. */
    /**
     * `true` ΓåÆ forwarded into whichever of `body`/`actions` renders, so a bar
     * whose price/CTA is not known yet (e.g. still loading enrollment status)
     * can shimmer instead of showing stale content.
     */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable ΓÇö it is already a prop.
     */
    classNames?: Array<AllowedClassName>
    /**
     * `true` ΓåÆ each region emits `` so a BlockAnatomy
     * panel can badge it on-render. Off in production.
     */
}

/**
 * A fixed bottom action bar pinned to the viewport edge ΓÇö owns the chrome
 * (fixed position, top divider, surface background, safe padding) so features
 * just drop a price + CTA inside. Typically `@app-md:hidden` for a mobile sticky
 * enroll/checkout bar.
 *
 * A bar is a horizontal row, so its named slots are `body` (leading) +
 * `actions` (trailing) rather than the vertical `header`/`body`/`footer` trio.
 * With only one of them the content renders RAW, so a full-width button or a
 * two-button decision row keeps its own sizing (`flex-1`, `w-full`).
 *
 * @param props - {@link PageBottomBarProps}
 */
const BottomBar = ({
    body,
    actions,
    isSkeleton = false,
    classNames,
}: PageBottomBarProps) => {
    const Main = body
    const Actions = actions
    const chrome = "fixed bottom-0 left-0 right-[var(--app-rail-w,0px)] z-40 border-t border-separator bg-background px-6 py-3"

    // Only ONE side supplied ΓåÆ render it raw: the caller's own width strategy
    // (`w-full` CTA, two `flex-1` buttons) must not be boxed by a shrink-0 wrapper.
    if (Main == null || Actions == null) {
        const Only = Main ?? Actions
        return (
            <div className={cn(chrome, classNames)} data-tier="composite" data-component="PageBottomBar">
                <div>{Only ? <Only isSkeleton={isSkeleton} /> : null}</div>
            </div>
        )
    }

    return (
        <div className={cn(chrome, classNames)} data-tier="composite" data-component="PageBottomBar">
            <StackH
                align="center"
                justify="between"
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                isSkeleton={isSkeleton}
                items={[
                    () => <div className="min-w-0"><Main isSkeleton={isSkeleton} /></div>,
                    () => <div className="shrink-0"><Actions isSkeleton={isSkeleton} /></div>,
                ]}
            />
        </div>
    )
}

/**
 * Page chrome members ΓÇö a route imports these by name:
 *
 * | Export | Content channel |
 * |---|---|
 * | `PageHeader` | `breadcrumb`/`title`/`description`/`actions`/`meta` (no children) |
 * | `PageBottomBar` | `body`/`actions` slots |
 */
export { Header as PageHeader, BottomBar as PageBottomBar }

