/**
 * The `header` channel of {@link Section}: either the PROPS of
 * {@link SectionHeader} (the frame builds it ΓÇö the main road) or a COMPONENT
 * reference (COMPOSITE-8, an escape hatch for a header the section did not
 * author, e.g. a toolbar row) ΓÇö the frame calls it itself so `isSkeleton` can
 * reach inside it.
 */
export type SectionHeaderSlot = SectionHeaderProps | ComponentTypeWithSkeleton

/** Props for {@link Section}. */
export interface SectionBaseProps {
    /**
     * Top region. Pass {@link SectionHeaderProps} (`{ title, descriptionΓÇª }`) and
     * the frame renders a {@link SectionHeader} itself; pass a COMPONENT
     * reference and the frame calls it itself, forwarding `isSkeleton`.
     */
    header?: SectionHeaderSlot
    /** Main region, as a COMPONENT reference (COMPOSITE-8) ΓÇö the frame calls it itself so `isSkeleton` can reach inside it. */
    body?: ComponentTypeWithSkeleton
    /** Bottom region (a closing CTA row, a caption, a "see more" link), as a COMPONENT reference (COMPOSITE-8) ΓÇö same contract as `body`. */
    footer?: ComponentTypeWithSkeleton
    /**
     * Vertical rhythm between header Γåö body Γåö footer, on the ┬º10c scale ONLY.
     * Default `{6}` (`gap-6`) ΓÇö the rhythm between regions of a page. Drop to
     * `{4}` (`gap-3`) when the header is just a label over a tight list.
     */
    gap?: AllowedGap
    /**
     * `true` ΓåÆ forwarded into whichever of `header`/`body`/`footer` renders
     * (COMPOSITE-8 ΓÇö each is a component reference this frame calls itself, so
     * the flag reaches inside every one of them).
     */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable ΓÇö it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/** A header slot is PROPS only when it is a plain object (not a component reference). */
const isHeaderProps = (header: SectionHeaderSlot): header is SectionHeaderProps =>
    typeof header === "object" && header !== null

/**
 * The region frame ΓÇö a semantic `<section>` that stacks header / body / footer at
 * ONE typed rhythm and nothing else. No fill, no border, no radius, no padding:
 * a section is a BAND of a page, so the surfaces live INSIDE it (its body is
 * usually a `SurfaceCard.*` / `SectionCard` / a grid of them).
 *
 * @param props - {@link SectionBaseProps}
 */
const Base = ({
    header,
    body: Body,
    footer: Footer,
    gap = 6,
    isSkeleton = false,
    classNames,
}: SectionBaseProps) => {
    let headerNode: ReactNode = null
    if (header != null) {
        if (isHeaderProps(header)) {
            // props form ΓåÆ the frame builds ITS OWN SectionHeader (a fixed internal
            // choice, not arbitrary caller content) ΓÇö badge that real component
            // directly rather than the generic wrapping div below.
            headerNode = <Header {...header} isSkeleton={isSkeleton} />
        } else {
            const HeaderSlot = header
            headerNode = <HeaderSlot isSkeleton={isSkeleton} />
        }
    }
    return (
        <section
            className={cn("flex flex-col", GAP_CLASS[gap], classNames)}

            data-tier="composite"
            data-component="Section"
            data-principle={gap === 6 ? "block-boundary" : undefined}
        >
            {headerNode != null ? (
                <div>{headerNode}</div>
            ) : null}
            {Body != null ? (
                <div><Body isSkeleton={isSkeleton} /></div>
            ) : null}
            {Footer != null ? (
                <div><Footer isSkeleton={isSkeleton} /></div>
            ) : null}
        </section>
    )
}

