    divider = false,
    onPress,
    href,
    isSkeleton = false,
    classNames,
}: ListRowProps) => {
    // Interactivity is a LOADED-state affordance only ΓÇö a loading row is inert,
    // same as the old separate `RowSkeleton` never wired a role/href/onClick.
    const isPressable = !isSkeleton && Boolean(onPress || href)

    const baseClassName = cn(
        "flex min-w-0 items-center gap-3 py-2",
        divider && "border-b border-separator",
        isPressable &&
            "rounded-2xl transition-colors hover:bg-surface-secondary focus-visible:bg-surface-secondary focus-visible:outline-none",
        classNames,
    )

    // One render path: `leading` is now a COMPONENT reference (COMPOSITE-8), so the
    // row calls it itself and forwards `isSkeleton` ΓÇö it decides how to shimmer, or
    // whether to shimmer at all; `title`/`subtitle` shimmer through `TitledText`'s
    // own `isSkeleton` (COMPOSITE-10 ΓÇö the atom draws its own bar, this row only
    // forwards the flag); `meta`/`trailing` are ALSO component references, but a
    // loading row still omits them entirely rather than call them ΓÇö that omission is
    // this composite's own call (COMPOSITE-10: it decides WHICH parts show).
    const content = (
        <>
            {Leading ? (
                <div className="shrink-0">
                    <Leading isSkeleton={isSkeleton} />
                </div>
            ) : null}
            <TitledText
                title={title}
                subtitle={subtitle}
                isSkeleton={isSkeleton}
                truncate

            />
            {!isSkeleton && (MetaSlot || TrailingSlot) ? (
                <Box principle="push-end" className="ml-auto"
                    explain="Pushes this peer to the trailing edge so trailing meta stays right-aligned in the row.">
                    <StackH
                        gap={3}
                        isSkeleton={isSkeleton}
                        classNames={["shrink-0"]}
                        items={[
                            ...(MetaSlot ? [() => <MetaSlot />] : []),
                            ...(TrailingSlot ? [() => <TrailingSlot />] : []),
                        ]}
                    />
                </Box>
            ) : null}
        </>
    )

    if (!isSkeleton && href) {
        return (
            <a href={href} onClick={onPress} className={baseClassName} data-tier="composite" data-component="ListRow" data-principle="content-row">
                {content}
            </a>
        )
    }

    if (!isSkeleton && onPress) {
        return (
            <div
                role="button"
                tabIndex={0}
                onClick={onPress}
                onKeyDown={(event) => {
                    if (event.key === "Enter" || event.key === " ") {
                        event.preventDefault()
                        onPress()
                    }
                }}
                className={cn(baseClassName, "cursor-pointer")}
                data-tier="composite"
                data-component="ListRow"
                data-principle="content-row"
            >
                {content}
            </div>
        )
    }

    return (
        <div className={baseClassName} data-tier="composite" data-component="ListRow" data-principle="content-row">
            {content}
        </div>
    )
}

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// .Labeled ΓÇö label + repeating list (+ CTA), no card frame (was `LabeledList`)
