/** Props for {@link ListToggleRow}. */
export interface ListToggleRowProps {
    /**
     * Row label ΓÇö short, single line (e.g. "Lock profile").
     */
    label: string
    /**
     * Optional muted hint under the label explaining what the toggle does.
     */
    description?: string
    /**
     * Current toggle state (controlled).
     */
    checked: boolean
    /**
     * Fires with the next state when the switch is toggled.
     */
    onCheckedChange: (checked: boolean) => void
    /**
     * Disables the switch (e.g. a lock row overriding a whole group). The row
     * also dims to signal it's inert, matching the hand-roll's
     * `aria-disabled` + opacity treatment on the gated section-visibility group.
     */
    isDisabled?: boolean
    /** Layout utilities on the row root, from the closed positioning union. */
    classNames?: Array<AllowedClassName>
    /** `true` ΓåÆ render the skeleton mirror (label + desc bars, switch pill). Consumer just flips the flag. */
    isSkeleton?: boolean
}

/**
 * Generic settings row: a label (+ optional muted description) on the left, a
 * house `Switch` pinned to the right. Presentational ΓÇö the caller owns
 * persistence/state; this row only reports the next boolean via
 * {@link ListToggleRowProps.onCheckedChange}.
 *
 * Grounded in the hand-roll toggle rows in `src/components/features/profile/
 * PrivacySettings` (the "lock profile" lock row + the per-section
 * visibility rows).
 *
 * @param props - {@link ListToggleRowProps}
 */
const ToggleRow = ({
    label,
    description,
    checked,
    onCheckedChange,
    isDisabled = false,
    classNames,
    isSkeleton = false,
}: ListToggleRowProps) => (
    // One outer shape whether loading or not: same wrapper, same `TitledText` call
    // (it forwards `isSkeleton` to its own atom ΓÇö COMPOSITE-10). Only the trailing
    // control itself still branches: the REAL control is the silent house `Switch`
    // (aria-label from the row label ΓÇö `ChoiceSwitch` would duplicate the visible
    // `TitledText` label); the SKELETON still mirrors through `ChoiceSwitch`
    // (a plain shimmer pill has no label to duplicate).
    <div className={cn(isDisabled && "opacity-50")}>
        <StackH
            gap={4}
            isSkeleton={isSkeleton}
            classNames={classNames}
            principle="label-field"
            explain="Form label above its field ΓÇö not title-subtitle, because the upper line labels an input rather than a heading pair."
            items={[
                () => (
                    <TitledText
                        title={label}
                        subtitle={description}
                        isSkeleton={isSkeleton}
                        classNames={["flex-1"]}

                    />
                ),
                () => isSkeleton ? (
                    <span className="shrink-0">
                        <ChoiceSwitch
                            isSkeleton
                            isSelected={false}
                            onValueChange={() => undefined}
                        />
                    </span>
                ) : (
                    <span className="shrink-0">
                        <Switch
                            isSelected={checked}
                            isDisabled={isDisabled}
                            onChange={onCheckedChange}
                            aria-label={label}
                        >
                            <SwitchContent>
                                <SwitchControl>
                                    <SwitchThumb />
                                </SwitchControl>
                            </SwitchContent>
                        </Switch>
                    </span>
                ),
            ]}
        />
    </div>
)

/**
 * The row/list FRAME namespace ΓÇö every "row ┬╖ list" frame in the design system,
 * one import, four members:
 *
 * | Member | Content channel |
 * |---|---|
 * | `.Row` | data props (`leading`/`title`/`subtitle`/`meta`/`trailing`) |
 * | `.Labeled` | `items` (children FORBIDDEN) |
 * | `.Meta` | `chip` + `items` |
 * | `.ToggleRow` | data props (`label`/`description`/`checked`) |
 */
export { Row as ListRow, Labeled as ListLabeled, Meta as ListMeta, ToggleRow as ListToggleRow }

/** Folder-matching compound namespace (export-matches-folder / ATOM-11 sync). */
export const List = {
    Row: Row,
    Labeled: Labeled,
    Meta: Meta,
    ToggleRow: ToggleRow,
} as const

import React, { type Key, type ReactNode } from "react"
import { cn } from "@heroui/react"
import {
