interface SizeConfig {
    titleSize: "sm" | "h3"
    titleWeight: "medium" | "semibold" | "bold"
    subSize: "xs" | "sm"
    /** `undefined` ΓåÆ foreground (default); `"muted"` ΓåÆ muted line. */
