import { Typography } from "@sb-components/atoms/text/Typography/Typography"
import type { AllowedClassName } from "@sb-components/atoms/_allowed-class-name"

/**
 * `MarkdownContent` ΓÇö a viewer that paints an authored markdown document faithfully. Unlike
 * other composites it cannot know its shape before rendering ΓÇö the payload decides it. Handles
 * Shiki-highlighted fenced code, mermaid diagrams (click-to-zoom, caption pairing),
 * `:::tab`/`:::code`/`:::preview` ΓåÆ PreviewΓåöCode tabs, GFM tables ΓåÆ HeroUI `Table`,
 * `::::accordion`/`:::panel` ΓåÆ HeroUI `Accordion`, plus `:::muted`/`:::chip`, image captions,
