 * Rewrites the `::::accordion` / `:::panel{title="ΓÇª"}` container directives into custom hast tags
 * the renderer map turns into a HeroUI Accordion (see `map.tsx`): `accordion`ΓåÆ`accordionblock`;
 * each `:::panel{title="ΓÇª"}`ΓåÆ`accordionpanel` carrying its `title` attribute. Inner panel content
 * (bullets, code fences) still renders through the normal handlers.
 *
 * Note: nesting needs MORE colons on the outer fence ΓÇö `::::accordion` wraps `:::panel`.
 * @param node - Current mdast node being walked.
 */
const applyAccordionDirective = (node: DirectiveNode): void => {
    if (node.type === "containerDirective") {
        if (node.name === "accordion") {
            const data = node.data || (node.data = {})
            data.hName = "accordionblock"
            data.hProperties = {}
