        thead: MarkdownTableHead,
        tbody: MarkdownTableBody,
        tr: MarkdownTableRow,
        th: MarkdownTableColumn,
        td: MarkdownTableCell,
        // A fenced block's inner `code` carries `language-*`; anything else is inline.
