        mutedblock: ({ children }: MarkdownNodeProps) => (
            <div className="text-sm font-semibold text-muted [&_*]:text-muted">{children}</div>
        ),
        mutedtext: ({ children }: MarkdownNodeProps) => (
            <span className="text-sm font-semibold text-muted">{children}</span>
        ),
        // Custom `:::chip` directive tag: a wrapped row of chips, one per authored keyword line.
        // Reuses the `Chip` ATOM (soft/neutral) rather than HeroUI `Chip` directly.
        chipblock: ({ items }: MarkdownChipBlockProps) => (
            <div className="my-2">
                <StackH
                    as="span"
                    at="sm"
                    gap={3}
                    principle="chip-row"
                    explain="Lets chips share one wrapping row so related tags stay together without stacking as a column."
                    items={String(items ?? "").split("|").filter(Boolean).map((keyword) => () => (
                        <Chip tone="default" text={keyword} />
                    ))}
                />
            </div>
        ),
        // :::tab ΓåÆ [ Preview | Code ] tabs; code/preview panes carry `kind` so `TabsBlock` matches them.
        tabblock: ({ children }: MarkdownNodeProps) => <TabsBlock>{children}</TabsBlock>,
        tabcode: ({ children }: MarkdownNodeProps) => <TabPane kind="code">{children}</TabPane>,
        tabpreview: ({ children }: MarkdownNodeProps) => <TabPane kind="preview">{children}</TabPane>,
        // ::::accordion / :::panel{title} ΓåÆ house `AccordionTree` compound (incremental panels from
        // react-markdown ΓÇö not the data-driven Disclosure `Accordion` atom). `variant="default"`
        // keeps the item separator FULL-BLEED, with the light hairline `--separator` re-point so
        // dividers read the same as the `SurfaceListCard` family; `border` delineates it as a
        // nested surface.
        accordionblock: ({ children }: MarkdownNodeProps) => (
            // `AccordionTree` omits `className` (atom door is closed); border/rhythm sit on the
            // wrapping seam so COMPOSITE-4 stays clean while the nested-surface look is preserved.
            <div className={cn("overflow-hidden border border-default bg-surface", blockMy)}>
                <AccordionTree
                    variant="default"
                    style={{ "--separator": "color-mix(in oklab, var(--surface-foreground) 6%, transparent)" } as React.CSSProperties}
                >
                    {children}
                </AccordionTree>
            </div>
        ),
        accordionpanel: ({ title, children }: MarkdownPanelProps) => (
            <AccordionTreeItem aria-label={String(title ?? "")}>
                <AccordionTreeHeading>
                    <AccordionTreeTrigger>
                        <div className="text-start">
                            <StackH
                                gap={4}
                                principle="content-row"
                                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                                justify="between"
                                items={[
                                    () => <span className={reading ? "text-base font-semibold" : "text-sm font-semibold"}>{title}</span>,
                                    () => <AccordionTreeIndicator />,
                                ]}
                            />
                        </div>
                    </AccordionTreeTrigger>
                </AccordionTreeHeading>
                <AccordionTreePanel>
                    <AccordionTreeBody>
                        <div className="space-y-2">{children}</div>
                    </AccordionTreeBody>
                </AccordionTreePanel>
            </AccordionTreeItem>
        ),
    }
}

import React from "react"

/**
 * STORYBOOK-LOCAL DESIGN SPEC ΓÇö faithful port of
 * `@/components/blocks/rendering/MarkdownContent/utils/markdown-table`. Authored
 * in Storybook (not `src`); synced back to `src` later.
 */

interface ElementWithChildren {
    children?: React.ReactNode
}

/** One `th`/`td` cell inside the HAST `tr` node backing a markdown table row. */
export interface MarkdownTableCellElement {
    /** HAST node type ΓÇö always `"element"` for a real cell. */
    type?: string
    /** Cell tag name ΓÇö `"th"` in a header row, `"td"` in a body row. */
    tagName?: string
}

/** The HAST `tr` element node react-markdown threads onto the `tr` renderer via `node`. */
export interface MarkdownTableRowElement {
    /** HAST node type ΓÇö always `"element"` for a real row. */
    type?: string
    /** The row's cell nodes. */
    children?: Array<MarkdownTableCellElement>
}

/**
 * Flattens thead row output (e.g. a fragment wrapping columns) so the columns can be
 * passed directly as children of HeroUI `Table.Header`.
 * @param children - Rendered children of the markdown `thead` element.
 * @returns A flat array of column or cell nodes.
 */
export function flattenMarkdownTableHeaderChildren(children: React.ReactNode): Array<React.ReactNode> {
    const flattened: Array<React.ReactNode> = []

    const pushRowCells = (rowChildren: React.ReactNode): void => {
        React.Children.forEach(rowChildren, (column) => {
            flattened.push(column)
        })
    }

    React.Children.forEach(children, (row) => {
        if (!React.isValidElement<ElementWithChildren>(row)) {
            return
        }
        if (row.type === React.Fragment) {
            React.Children.forEach(row.props.children, (nestedRow) => {
                if (!React.isValidElement<ElementWithChildren>(nestedRow)) {
                    return
                }
                pushRowCells(nestedRow.props.children)
            })
            return
        }
        pushRowCells(row.props.children)
    })
    return flattened
}

/**
 * Detects header rows from the original HAST `tr` node (GFM uses `th` cells in thead).
 * @param node - The HAST node backing the markdown `tr` element.
 * @returns True when every child cell is a `th` element (i.e. a header row).
 */
export function isMarkdownHeaderTableRowNode(node: unknown): boolean {
    if (!node || typeof node !== "object") {
        return false
    }
    const element = node as MarkdownTableRowElement
    if (element.type !== "element") {
        return false
    }
    if (!Array.isArray(element.children) || element.children.length === 0) {
        return false
    }
    return element.children.every(
        (child) =>
            child.type === "element" &&
            typeof child.tagName === "string" &&
            child.tagName.toLowerCase() === "th",
    )
}

