// Shared message-frame plumbing (.Empty / .Error)
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/** Shared props of the two MESSAGE frames `.Empty` / `.Error`. */
interface MessageProps {
    /** Main line (already translated). `string`, not `ReactNode` ΓÇö the frame forwards it into `EmptyState`, which renders it (COMPOSITE-8). */
    title: string
    /** Secondary line under the title (already translated). Optional. `string` for the same reason as {@link MessageProps.title}. */
    description?: string
    /**
     * Override the default glyph ΓÇö takes a **COMPONENT REF** (`icon={TrayIcon}`), NOT
     * JSX. ┬º14b: the caller (especially a SCREEN) must not hold a pre-built node. The
     * frame owns the scale + `weight="duotone"` (┬º4/┬º5) so every empty/error in the
     * system speaks with the same glyph voice ΓÇö the caller only picks "which glyph",
     * not "what it looks like".
     */
    icon?: PhosphorIcon
    /**
     * General ACTION slot below the description ΓÇö a COMPONENT reference (COMPOSITE-8),
     * never a built node (a `Button`, a two-button clusterΓÇª): forwarded straight into
     * `EmptyState`'s own `action` slot, which calls it and forwards `isSkeleton`. WINS
     * over the `onRetry`/`retryLabel` shorthand when both are passed.
     */
    action?: ComponentTypeWithSkeleton
    /** Shorthand: retry handler ΓÇö only renders a button when PAIRED with `retryLabel`. */
    onRetry?: () => void
    /** Shorthand: the (already translated) label of the retry button ΓÇö required for the button to appear. `string`, not `ReactNode` (COMPOSITE-8). */
    retryLabel?: string
    /**
     * Where this sits inside its parent. Appearance is not passable ΓÇö it is already a prop.
     */
    classNames?: Array<AllowedClassName>
    /**
     * Caller identity to wear on this message frame's root instead of its own ΓÇö pass this when
     * a `block`/`layout`/`overlay`/`page` component (BLOCK-2: never draws a shape of its own)
     * is using this empty/error message AS its root element, instead of wrapping it in a raw
     * `<div data-tier=ΓÇª data-component=ΓÇª>`. See `_identity.ts`. Omitted ΓåÆ this frame keeps
     * emitting no `data-tier`/`data-component` of its own, unchanged (the nested `EmptyState`
     * still carries ITS OWN composite identity either way ΓÇö composites always name themselves).
     */
    identity?: CallerIdentity
}

/**
 * Force `weight="duotone"` on the message frame's glyph ΓÇö ┬º4/┬º5: the FRAME owns
 * how the glyph looks, the caller only picks which glyph. Before 2026-07-25 the
 * frame took `icon?: ReactNode`, so each caller decided its own weight ΓåÆ they had
 * already drifted (story duotone, screen not). The old `nodeAsIcon` adapter was
 * removed per its own debt note.
 */
const withDuotone = (Icon: PhosphorIcon): EmptyStateIcon => {
    const Glyph = (props: SVGProps<SVGSVGElement>) => <Icon {...props} weight="duotone" />
    return Glyph
}

/**
 * Resolve the `action` slot's COMPONENT: a free-form `action` component reference
 * wins; otherwise the `onRetry` + `retryLabel` pair is wrapped into a component
 * rendering a secondary size-sm `Button`. Returns a component reference (never a
 * built node, COMPOSITE-8) ΓÇö `EmptyState` calls it itself, forwarding `isSkeleton`.
 */
const composeAction = ({ action, onRetry, retryLabel }: MessageProps): ComponentTypeWithSkeleton | undefined => {
    if (action) {
        return action
    }
    if (onRetry && retryLabel) {
        return () => (
            <Button
                variant="tertiary"
                size="sm"
                onPress={onRetry}
                label={retryLabel}
            />
        )
    }
    return undefined
}

