/** Props for {@link AsyncContentEmpty} ΓÇö the empty-message frame (props-only). */
export type AsyncContentEmptyProps = MessageProps

/**
 * A standalone EMPTY-MESSAGE frame ΓÇö tray icon, title + optional description,
 * and an action slot (or the "retry" shorthand), centred. This is the standard
 * `emptyContent` for {@link AsyncContent}.
 *
 * A THIN layer over the `EmptyState` frame: it only adds the default
 * `TrayIcon` and wraps `onRetry`/`retryLabel` into a button for the `action`
 * slot ΓÇö it does NOT redraw the icon + title + description + button itself.
 *
 * @param props - {@link AsyncContentEmptyProps}
 */
const Empty = (props: AsyncContentEmptyProps) => {
    const { title, description, icon, classNames, identity } = props
    // The caller's identity is FORWARDED to `EmptyState` ΓÇö the element actually drawn here ΓÇö
    // never wrapped in a div of our own. A wrapper would be a shape this tier must not draw.
    return (
        <EmptyState
            identity={identity}
            classNames={classNames}
            icon={withDuotone(icon ?? TrayIcon)}
            title={title}
            description={description}
            action={composeAction(props)}
        />
    )
}

