import React from "react"
import type { ReactNode } from "react"
import { cn } from "@heroui/react"
import { Button } from "@/components/atoms/buttons/Button"
import {
    ButtonGroupRoot,
    ButtonGroupSeparator,
} from "@/components/atoms/buttons/ButtonGroup"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"

/**
 * `Button.RadioGroup` ΓÇö a flex-wrap row of selectable buttons, single- or multi-select.
 * Leaves: `items` builds N child buttons (`Default`, with per-item `isDisabled`); `multiple`
 * allows ΓëÑ2 selected at once; `trailing` appends a non-option button (e.g. "+N"); `itemAction`
 * turns each item into a fused `ButtonGroup` [select | delete | more].
 */

interface CloneableActionElementProps {
    children?: ReactNode
}

/** One selectable button in a {@link ButtonRadioGroup}. */
export interface ButtonRadioGroupItem<T extends string> {
    /** Value selected when this button is chosen. */
    value: T
    /** Button content (icon + label + meta ΓÇö caller-defined inline row). */
    content: ReactNode
    /** When true the button is dimmed and not selectable. */
    isDisabled?: boolean
}

/** Props shared by both the single- and multi-select modes of {@link ButtonRadioGroup}. */
interface ButtonRadioGroupBaseProps<T extends string> {
    /** The selectable buttons. */
    items: Array<ButtonRadioGroupItem<T>>
    /** Accessible label for the group. */
    ariaLabel: string
    /**
     * Optional trailing node placed after the buttons in the SAME row (e.g. a
     * "+N" overflow button). Not part of the group's value ΓÇö it's an action.
     */
    trailing?: ReactNode
    /**
     * Optional per-item trailing action(s) ΓÇö e.g. a delete button and/or a "Γï«"
     * (kebab) menu trigger. When provided, the item's select button and these
     * action buttons render as ONE connected `ButtonGroup` per item
     * (`[select | delete | Γï«]`). Return the action `<Button>`s as an ARRAY (with
     * `key`s) so each is an individual segment. Omit for a plain single-select row.
     */
    itemAction?: (item: ButtonRadioGroupItem<T>) => ReactNode
    /**
     * Where this sits inside its parent. Appearance is not passable ΓÇö it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/** Single-select mode (default) ΓÇö exactly one value selected at a time. */
interface ButtonRadioGroupSingleProps<T extends string> extends ButtonRadioGroupBaseProps<T> {
    /** Single-select ΓÇö omit or pass `false`. */
    multiple?: false
    /** Currently selected value. */
    value: T
    /** Fired with the chosen value when a button is selected. */
    onChange: (value: T) => void
}

/**
 * Multi-select mode ΓÇö a SET of values, each button an independent toggle. The
 * caller owns the set + the toggle logic (e.g. enforcing "at least one selected");
 * this component only reports which button was pressed via {@link onToggle}.
 */
interface ButtonRadioGroupMultiProps<T extends string> extends ButtonRadioGroupBaseProps<T> {
    /** Multi-select ΓÇö pass `true`. */
    multiple: true
    /** Currently selected values. */
    values: Array<T>
    /** Fired with the pressed value (the caller adds/removes it from its own set). */
    onToggle: (value: T) => void
}

/** Props for {@link ButtonRadioGroup} ΓÇö a discriminated union on `multiple`. */
export type ButtonRadioGroupProps<T extends string> =
    | ButtonRadioGroupSingleProps<T>
    | ButtonRadioGroupMultiProps<T>

/** Source-level tier metadata ΓÇö see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "ButtonRadioGroup" } as const

/**
 * A single-select toggle-button group laid out as a flex-wrap row (buttons wrap
 * to the next line, never scroll). Every option is a house `<Button>`:
 * standalone, selected = filled `tertiary` (NEUTRAL, not accent ΓÇö a facet/config
 * toggle isn't a CTA), unselected = hollow `ghost`. NEVER `primary` here ΓÇö a config
 * row commonly sits on the SAME surface as the page's one accent CTA.
 *
 * When `itemAction` is supplied, each item instead renders as one connected
 * `ButtonGroup` ΓÇö the select button + its action button(s) touching, only the
 * two outer ends rounded (`[select | delete | Γï«]`). The seam is the house
 * `ButtonGroupSeparator`, baked to the `--border` token and full-height.
 *
 * `role="group"` + `aria-pressed` per option ΓÇö works for BOTH the default
 * single-select toggle group and the multi-select mode. House `Button` does not
 * accept `aria-pressed`, so the standalone path wraps the control in a span;
 * the fused `ButtonGroupRoot` path cannot wrap (segments must be buttons), so
 * pressed state is carried only on the standalone span.
 *
 * @param props - {@link ButtonRadioGroupProps}
 */
export const ButtonRadioGroup = <T extends string>(props: ButtonRadioGroupProps<T>) => {
    const { items, ariaLabel, trailing, itemAction, classNames } = props
    // narrow the discriminated union once ΓÇö selection state + the press handler are
    // the only things that differ between single- and multi-select.
    const isSelected = (candidate: T): boolean =>
        (props.multiple ? props.values.includes(candidate) : props.value === candidate)
    const handlePress = (candidate: T): void => {
        if (props.multiple) {
            props.onToggle(candidate)
        } else {
            props.onChange(candidate)
        }
    }
    return (
        <div
            role="group"
            aria-label={ariaLabel}
            className={cn("flex flex-wrap items-center gap-2", classNames)}
            data-tier="composite"
            data-component="ButtonRadioGroup"
            data-principle="flex-action"
        >
            {items.map((item) => {
                const selected = isSelected(item.value)
                if (!itemAction) {
                    // standalone: selected = filled `tertiary`, unselected = hollow `ghost`.
                    return (
                        <span key={item.value} aria-pressed={selected}>
                            <Button
                                size="sm"
                                variant={selected ? "tertiary" : "ghost"}
                                isDisabled={item.isDisabled}
                                onPress={() => handlePress(item.value)}
                                label={item.content}
                            />
                        </span>
                    )
                }
                // select button + its action(s) = one connected ButtonGroup per item.
                // Each action button gets a `ButtonGroupSeparator` injected at the head
                // of its children ΓÇö the separator must sit inside the following button.
                return (
                    <ButtonGroupRoot key={item.value} size="sm">
                        <Button
                            size="sm"
                            variant={selected ? "secondary" : "tertiary"}
                            isDisabled={item.isDisabled}
                            onPress={() => handlePress(item.value)}
                            label={item.content}
                        />
                        {React.Children.map(itemAction(item), (action) =>
                            React.isValidElement<CloneableActionElementProps>(action)
                                ? React.cloneElement(
                                    action,
                                    undefined,
                                    <ButtonGroupSeparator />,
                                    action.props.children,
                                )
                                : action,
                        )}
                    </ButtonGroupRoot>
                )
            })}
            {trailing}
        </div>
    )
}

import React from "react"
import type { ReactNode } from "react"
import { CheckCircleIcon, XCircleIcon } from "@phosphor-icons/react"
import { Tooltip } from "@/components/atoms/overlay/Tooltip"
import { Chip } from "@/components/atoms/chips/Chip"
import type { ChipTone, IconComponent } from "@/components/atoms/chips/Chip"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"

/**
 * STORYBOOK-LOCAL DESIGN SPEC ΓÇö ported faithfully from
 * `@/components/composites/chips/EnumChip`. Authored in Storybook (not `src`); synced later.
 */

/**
 * HeroUI soft-chip colors usable by an {@link EnumChip}.
 *
 * Alias, not a redeclaration (teacher finalized 2026-07-29): the exact same five
 * values `Chip`'s own `ChipTone` already carries ΓÇö this used to need
 * `COLOR_TO_TONE` to translate `default ΓåÆ neutral` between two hand-typed
 * copies of the same vocabulary. Both sides being the same alias makes the
 * translation a no-op, so it is gone, not renamed.
 *
 * Aliases `ChipTone` specifically (NOT `AlertStatus`, round-9, 2026-07-30):
 * `entry.color` flows straight into `Chip`'s `tone`, a vendor-constrained prop
 * ΓÇö `ChipTone` is the one guaranteed to match it 1:1 (see `ChipTone`'s own
 * note on why it split from `AlertStatus` when `info` was added there).
 */
export type EnumChipColor = ChipTone


/**
 * The ONLY icons an {@link EnumChipEntry} can name ΓÇö a CLOSED set, not an
 * arbitrary `IconComponent`. AUDIT 2026-07-30 (feedback ChallengePage/Graded
 * round-2, teacher finalized): a string selector like `ListMark`
 * (`SurfaceCard.tsx`'s own "check"/"cross"/"pending"/"none" vocabulary), NOT
 * a raw icon reference ΓÇö narrowing to a curated set is the whole point of
 * "universal" symbols (┬º2a: check/cross, nothing caller-chosen). Extend this
 * union the day a THIRD symbol earns the same bar, don't loosen the type.
 */
export type EnumChipIcon = "check" | "cross"

const ENUM_CHIP_ICON_MAP: Record<EnumChipIcon, IconComponent> = {
    check: CheckCircleIcon,
    cross: XCircleIcon}

/** One enum value's chip presentation. */
export interface EnumChipEntry {
    /** Soft chip color. Omit to use the Chip default. */
    color?: EnumChipColor
    /** Visible label (already localized by the caller). */
    label: ReactNode
    /** Optional tooltip (already localized); wraps the chip in a Tooltip when set. */
    tooltip?: ReactNode
    /**
     * Optional leading icon ΓÇö one of {@link EnumChipIcon}, not a component.
     * Omit for every existing map entry that never had one; only add where
     * the value itself is a "universal" symbol, e.g. a failed/not-passed
     * verdict (AUDIT 2026-07-30, feedback ChallengePage/Graded round-2).
     */
    icon?: EnumChipIcon
}

/** Props for {@link EnumChip}. */
export interface EnumChipProps<E extends string> {
    /** The current enum value; looked up in {@link map}. */
    value: E
    /** Map from enum value to presentation (accepts Partial ΓÇö unhandled values throw). */
    map: Partial<Record<E, EnumChipEntry>>
    /**
     * @deprecated pass `classNames` instead ΓÇö a free string cannot be constrained.
     * Kept only for the two `_legacy` callers (`HostPlatformChip`, `EntityResultRow`)
     * that still pass a free-form string; `_legacy` is off-limits to edit, so this
     * escape stays until those callers are retired (ATOM-5 narrowing pass, 2026-07-31).
     */
    className?: string
    /**
     * Extra classes on the chip. Prefer this over `className`; the string form is going
     * away. This value is handed straight to `Chip`'s own closed `classNames` union, so
     * an unconstrained string here would only fail one tier down.
     */
    classNames?: Array<AllowedClassName>
    /** When `true`, renders the skeleton placeholder (a chip-shaped pill) instead of the real chip. */
    isSkeleton?: boolean
}

/**
 * The canonical "enum ΓåÆ soft chip" composite: a `Chip` whose
 * tone / label / optional tooltip / optional leading icon come from a per-value map.
 * Domain badges (AI-model category, difficulty, video host ΓÇª) shrink to just their map
 * table + this delegate. Deliberately does NOT force width.
 *
 * Γ¡É AUDIT 2026-07-30 (feedback ChallengePage/Graded round-2): gained `icon` per entry
 * (was "text-only, no leading icon"). Additive, per-value ΓÇö most maps stay text-only;
 * a value only gets an icon when it is a "universal" symbol (check/cross), not a habit.
 *
 * ΓÜá∩╕Å Changed 2026-07-26: this used to be built on top of `StatusChip` ΓÇö that component
 * was removed because it was just `Chip` with `tone` hardcoded, adding no behavior. Now
 * it calls the atom directly.
 *
 * @param props - {@link EnumChipProps}
 */
/** Source-level tier metadata ΓÇö see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "EnumChip" } as const

/** Renders a `Chip` whose tone, label, icon and tooltip come from a per-enum-value map. */
export const EnumChip = <E extends string>({ value, map, className, classNames, isSkeleton}: EnumChipProps<E>) => {
    if (isSkeleton) {
        // NO LONGER patching on a `h-6` here: the atom's shimmer used to be `h-7` tall,
        // 4px off from the real chip box, so the call site had to patch the shape for it.
        // The atom has since been fixed (2026-07-26) ΓÇö a call site having to patch the
        // atom's shape is a sign the atom is wrong, not that this spot is wrong.
        // `Chip` no longer takes a free `className`; the legacy string (kept only for
        // the two `_legacy` callers) wraps a div instead.
        const skeletonChip = <Chip isSkeleton classNames={classNames} />
        return className ? <div className={className}>{skeletonChip}</div> : skeletonChip
    }
    const entry = map[value]
    if (!entry) {
        throw new Error(`EnumChip: no map entry for value "${value}"`)
    }
    const chip = (
        <Chip
            tone={entry.color ?? "default"}
            classNames={classNames}
            text={entry.label}
            icon={entry.icon != null ? ENUM_CHIP_ICON_MAP[entry.icon] : undefined}
        />
    )
    const wrappedChip = className ? <div className={className}>{chip}</div> : chip
    if (entry.tooltip == null) {
        return wrappedChip
    }
    return (
        <Tooltip label={entry.tooltip}>{wrappedChip}</Tooltip>
    )
}

