    hint?: string
    /** `true` ΓåÆ a TOTAL row: label goes to foreground medium, value goes to base size + bold. */
    emphasis?: boolean
    /** `true` ΓåÆ draws a SEPARATOR line below the row (seam between this row and the next). */
    divider?: boolean
    /** Gap between the row's content and the `divider` line (┬º10). Default `4` (`gap-3`). */
