/**
 * Props for {@link KeyValueRow}. `label`/`value` are REQUIRED unless `isSkeleton`
 * (┬º12b) ΓÇö a shimmer row has no real pair to show yet.
 */
export type KeyValueRowProps = KeyValueRowOwnProps &
    (
        | { isSkeleton: true; label?: string; value?: string }
        | { isSkeleton?: false; label: string; value: string }
    )

/**
 * One labelΓÇôvalue row: label (+`hint`) sits left, value sits right, `tabular-nums`
 * keeps the digits aligned in a column when rows stack (┬º3). `emphasis` is the
 * STRESS level for a total row.
 *
 * @param props - {@link KeyValueRowProps}
 */
const KeyValueRow = ({
    label,
    value,
    hint,
    emphasis = false,
    divider = false,
    gap = 4,
    copyable = false,
    isSkeleton = false,
    classNames}: KeyValueRowProps) => {
