/** ONE row in {@link KeyValueList} ΓÇö described as DATA, not JSX. */
export interface KeyValueListItem {
    /** React key. */
    key: string
    /** Label (left side). `string` ΓÇö the row wraps it in `Typography` itself. */
    label: string
    /** Value (right side) ΓÇö an already-formatted `string` (COMPOSITE-8). */
    value: string
    /** Sub-line below the label. Plain `string` ΓÇö see {@link KeyValueRowOwnProps.hint}. */
    hint?: string
    /** `true` ΓåÆ a TOTAL row (visual emphasis). */
    emphasis?: boolean
    /** `true` ΓåÆ this row gets the {@link KeyValueRowOwnProps.copyable} copy affordance. */
    copyable?: boolean
}

/** Props for {@link KeyValueList}. */
export interface KeyValueListProps {
    /** The rows, in reading order. REQUIRED ΓÇö a repeated list = data (┬º13b). */
    items: ReadonlyArray<KeyValueListItem>
    /** Gap between rows, ENFORCED by the ┬º10 scale. Default `4` (`gap-3`, vertical rows). */
    gap?: AllowedGap
    /** `true` ΓåÆ draws a separator line BETWEEN rows (the last row has none). */
    divider?: boolean
    /**
     * `true` ΓåÆ render `skeletonRows` placeholder rows instead of `items` (same
     * contract as `List.Labeled`'s own `isSkeleton`/`skeletonRows` pair).
     */
    isSkeleton?: boolean
    /** Placeholder row count while `isSkeleton`. Defaults to `3`. */
    skeletonRows?: number
    /**
     * Anatomy tag for THIS composite itself ΓÇö lets the PARENT badge it as ONE node (┬º11a.1).
     * Without this prop the composite doesn't make it into the Deps tree: using a
     * `frame`/`composite` tier node that the panel can't see counts as not using it.
     */
    /**
     * Where this sits inside its parent. Appearance is not passable ΓÇö it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
