 * enabled) is decided by the LIST ΓÇö the LAST row has none, so the seam always sits
 * BETWEEN two rows instead of leaving a stray line dangling at the bottom. The gap
 * around each row-and-line shares the list's `gap` ΓçÆ the rhythm above/below the line
 * is always even (┬º10a: one seam, one owner).
 *
 * @param props - {@link KeyValueListProps}
 */
const KeyValueList = ({
    items,
    gap = 4,
    divider = false,
    isSkeleton = false,
    skeletonRows = 3,
    classNames}: KeyValueListProps) => (
    <div
        className={cn("flex flex-col", GAP_CLASS[gap], classNames)}
        data-tier="composite"
        data-component="KeyValueList"
    >
        {isSkeleton
            ? Array.from({ length: skeletonRows }, (_unused, index) => (
                <KeyValueRow key={index} isSkeleton divider={divider && index < skeletonRows - 1} gap={gap} />
            ))
            : items.map(({ key, ...item }, index) => (
                <KeyValueRow
                    key={key}
                    {...item}
                    divider={divider && index < items.length - 1}
                    gap={gap}
                />
            ))}
    </div>
)

/**
 * `KeyValue.*` ΓÇö the labelΓÇôvalue pair composite (COMPOSITE tier ┬º13). `Row` (one pair) ┬╖
 * `List` (N pairs, `items`). Visual variants = PROP (`emphasis`/`divider`), ┬º6b.
 */
export { KeyValueRow, KeyValueList }

/** Folder-matching compound namespace (export-matches-folder). Existing named exports stay public. */
export const KeyValue = {
    Row: KeyValueRow,
    List: KeyValueList,
} as const

import type { ComponentType, SVGProps } from "react"
import { Alert, type AlertStatus } from "@/components/atoms/feedback/Alert"
import { Button } from "@/components/atoms/buttons/Button"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"

/**
 * ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
 * STORYBOOK-LOCAL DESIGN SPEC ΓÇö `Callout`, a tinted flat strip LIVING INSIDE a
 * surface (`title`/`description`/`body`/`action`).
 *
 * ΓÜá∩╕Å Split out of the `Feedback.*` namespace (2026-08-01) back into its own flat
 * file ΓÇö the 2026-07-25 consolidation grouped `Callout`/`Empty`/`Confirm` under
 * one `Feedback` folder; this reverses that so each frame is discoverable by
 * its own name again. Props/behaviour are UNCHANGED ΓÇö this is a file-location +
 * naming refactor, not a visual or API change.
 *
 * ATOM COMPOSITION (┬º12): text goes through `Typography.*`, buttons through
 * `Button.*`, icons come from `@phosphor-icons/react` ΓÇö ONE SET ONLY (┬º5Γâú0),
 * passed as a component ref, the frame forces size/weight itself (┬º4/┬º5).
 * DELIBERATE EXCEPTION: keeps HeroUI's `Alert.Title`/`Alert.Description`
 * because HeroUI itself carries the COLOR-BY-STATUS contract (`.alert--warning
 * .alert__title` ΓåÆ `text-warning-soft-foreground`). Swapping in `Typography` would
 * mean hand-feeding a color table ΓÇö that's the real "hand-rolled". Switch to the
 * atom once an `Alert` atom exists.
 * ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
 */

/** Source-level tier metadata ΓÇö see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "Callout" } as const

/** Semantic tone ΓÇö the atom's `AlertStatus` re-exported under this frame's name. */
export type CalloutStatus = AlertStatus

/** Icon passed as a COMPONENT (phosphor), never JSX ΓÇö the frame owns its scale (┬º4/┬º5). */
export type CalloutIcon = ComponentType<SVGProps<SVGSVGElement>>

/**
 * Action button bg/text per status ΓÇö SOLID `bg-<status>` CTA against the lighter
 * tint. INTERNAL: the CTA lived in the caller's `action` slot in the old shape,
 * so the caller had to hold `Button` and apply the skin itself. Now the frame
 * builds the button ITSELF from `actionLabel`/`onAction` ΓçÆ the caller
 * (especially a SCREEN) no longer touches the atom.
 */
const CALLOUT_ACTION_CLASS: Record<CalloutStatus, string> = {
    default: "bg-foreground text-background",
    accent: "bg-accent text-accent-foreground",
    success: "bg-success text-success-foreground",
    warning: "bg-warning text-warning-foreground",
    danger: "bg-danger text-danger-foreground",
    info: "bg-info text-info-foreground",
}

/** Props SPECIFIC to {@link Callout} ΓÇö EXCEPT the `title`/`isSkeleton` pair (see {@link CalloutProps}). */
interface CalloutOwnProps {
    /** Semantic tone (drives tint + icon/title colour). Default `"default"`. */
    status?: CalloutStatus
    /**
     * Optional supporting line under the title ΓÇö the body TEXT slot. `string`,
     * not `ReactNode` (COMPOSITE-8) ΓÇö forwarded straight into `Alert`, which
     * renders it (or a shimmer bar in its place) itself.
     */
    description?: string
    /**
     * Optional free-form body region under `description` (a short list, a meta
     * row). A COMPONENT reference, not a built node (COMPOSITE-8) ΓÇö the frame
     * calls it itself with `isSkeleton` forwarded before handing the result to
     * `Alert`'s own `body` slot.
     */
    body?: ComponentTypeWithSkeleton
    /** Optional custom indicator icon as a COMPONENT; omit for the status default. */
    icon?: CalloutIcon
    /**
     * CTA label (footer slot). The frame builds the button ITSELF and applies the
     * skin per `status` ΓÇö the caller only supplies TEXT, not a `Button` (a screen
     * must not hold the atom).
     */
    actionLabel?: string
    /** Handler for the CTA; the button only shows once `actionLabel` is also present. */
    onAction?: () => void
    /** When provided, renders a status-coloured close (├ù) wired to this. */
    onClose?: () => void
    /** Accessible label for the close button. */
    closeAriaLabel?: string
    /**
     * Where this sits inside its parent. Appearance is not passable ΓÇö it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * `isSkeleton` is a co-located loading state ΓÇö forwarded straight into `Alert`,
 * which owns drawing the shimmer bars. `title` is optional only in the
 * `isSkeleton: true` branch; the live branch still requires it. `string`, not
 * `ReactNode` (COMPOSITE-8) ΓÇö the frame hands it to `Alert`'s own `title` slot.
 */
export type CalloutProps = CalloutOwnProps &
    (
        | { isSkeleton: true; title?: string }
        | { isSkeleton?: false; title: string }
    )

/**
 * A tinted, flat note for use INSIDE a card / surface (surface-in-surface): a thin
 * `bg-<status>-soft` + `shadow-none` highlight strip, so it doesn't read as a
 * card-in-card.
 *
 * A thin FRAME around the `Alert` atom: callout = an alert PLACED INSIDE a
 * surface, so the frame only picks `tone="soft"` + glyph `md` and hands the
 * whole skin (tint ┬╖ icon per valence ┬╖ ├ù button) to the atom. The frame used
 * to hand-feed three color tables in parallel with `Toast` ΓÇö that was drift,
 * now removed.
 *
 * @param props - {@link CalloutProps}
 */
export const Callout = (props: CalloutProps) => {
    const {
        status = "default",
        description,
        body: Body,
        icon,
        actionLabel,
        onAction,
        onClose,
        closeAriaLabel,
        classNames,
    } = props
    // Narrowed off the discriminant so `title` stays required in the live branch ΓÇö
    // destructuring it straight off `props` above would widen it to `string | undefined`
    // and lose exactly that guarantee (same shape `Alert`/`Toast` already use).
    const content = props.isSkeleton
        ? ({ isSkeleton: true, title: props.title } as const)
        : ({ isSkeleton: false, title: props.title } as const)
    return (
        <Alert
            status={status}
            tone="soft"
            {...content}
            description={description}
            body={Body ? <Body isSkeleton={props.isSkeleton} /> : undefined}
            icon={icon}
            action={
                actionLabel ? (
                    // The frame owns the CTA: builds the button + applies skin per status itself. Caller only supplies text.
                    // Button is an atom ΓÇö it owns its own appearance, so the per-status skin wraps a div rather than reaching into the atom.
                    <div className={CALLOUT_ACTION_CLASS[status]}>
                        <Button label={actionLabel} size="sm" onPress={onAction} />
                    </div>
                ) : undefined
            }
            onClose={onClose}
            closeAriaLabel={closeAriaLabel}
            classNames={classNames}
        />
    )
}

