        icon: Icon,
        code,
        description,
        body: Body,
        action: Action,
        tone = "neutral",
        size = "default",
        classNames,
        identity,
    } = props
    const isSkeleton = props.isSkeleton ?? false
    // Narrowed off the discriminant so `title` stays required in the live branch ΓÇö
    // destructuring it straight off `props` above would widen it to `string | undefined`
    // and lose exactly that guarantee (same shape `Alert`/`Toast` already use).
    const titleContent = props.isSkeleton
        ? ({ isSkeleton: true, text: props.title } as const)
        : ({ isSkeleton: false, text: props.title } as const)
    // Same discriminant trick for the optional strings below ΓÇö `isSkeleton` must stay the
    // exact `true`/`false` literal, not the widened `boolean` this frame's own flag would
    // give, because `Typography`'s prop type is the same kind of union.
    const skeletonAttrs = isSkeleton ? ({ isSkeleton: true } as const) : ({ isSkeleton: false } as const)

    if (size === "compact") {
        // ΓÜá∩╕Å The `Typography.*` atom does NOT accept unknown props (no rest spread) ΓåÆ every
        // anatomy tag must sit on a WRAPPING element, not be stuffed into the atom.
        return (
            <span
                className={cn("block", classNames)}
                {...resolveIdentity(identity, { tier: "composite", name: "EmptyState" })}
            >
                <Typography size="sm" color="muted" {...titleContent} />
            </span>
        )
    }

    const isPage = size === "page"

    return (
        <div
            className={cn(
                isPage
                    ? "mx-auto flex min-h-[70vh] max-w-xl flex-col items-center justify-center gap-6 px-6 py-8 text-center"
                    : "flex flex-col items-center gap-3 py-6 text-center",
                classNames,
            )}
            {...resolveIdentity(identity, { tier: "composite", name: "EmptyState" })}
        >
            {code != null ? (
                <div>
                    <Typography size="h1" weight="bold" color="muted" text={code} {...skeletonAttrs} />
                </div>
            ) : null}
            {Icon ? (
                <span className={cn("inline-flex", tone === "danger" ? "text-danger" : "text-foreground")}>
                    <Icon className="size-8" />
                </span>
            ) : null}
            {isPage ? (
                <StackV
                    gap={3}
                    principle="sibling-stack"
                    explain="Same-kind peer stack ΓÇö not group-boundary, because these items are repeating siblings rather than section groups."
                    isSkeleton={isSkeleton}
                    items={[
                        () => (
                            <div>
                                <Typography size="h4" weight="semibold" align="center" {...titleContent} />
                            </div>
                        ),
                        ...(description
                            ? [() => (
                                <div>
                                    <Typography size="sm" color="muted" text={description} {...skeletonAttrs} />
                                </div>
                            )]
                            : []),
                    ]}
                />
            ) : (
                <>
                    <div>
                        <Typography weight="medium" {...titleContent} />
                    </div>
                    {description ? (
                        <div>
                            <Typography size="xs" color="muted" text={description} {...skeletonAttrs} />
                        </div>
                    ) : null}
                </>
            )}
            {Body ? <div><Body isSkeleton={isSkeleton} /></div> : null}
            {Action ? (
                <div className={isPage ? "flex flex-wrap items-center justify-center gap-3" : undefined}>
                    <Action isSkeleton={isSkeleton} />
                </div>
            ) : null}
        </div>
    )
}

import type { ComponentType, SVGProps } from "react"
import { cn } from "@heroui/react"
import { ImageIcon } from "@phosphor-icons/react"
import { useDropzone } from "react-dropzone"
import { Typography } from "@/components/atoms/text/Typography"

/**
 * Icon stroke weight accepted by {@link IconComponent}. Kept generic so the
 * composite is not locked to one icon library.
 */
export type IconWeight = "regular" | "bold"

/**
 * Icon passed as a component reference (e.g. `CameraIcon`). The composite
 * renders it at the dropzone's own size.
 */
export type IconComponent = ComponentType<SVGProps<SVGSVGElement> & { weight?: IconWeight }>

/** Max image size in bytes (5 MB). */
const MAX_SIZE = 5 * 1024 * 1024

/** Accepted image MIME types. */
const ACCEPT = {
    "image/png": [],
    "image/jpeg": [],
    "image/webp": [],
    "image/gif": [],
}

/** Props for {@link ImageDropzone}. */
export interface ImageDropzoneProps {
    /** Called with the dropped or picked image file after type and size filters. */
    onFile: (file: File) => void
    /** Primary call to action (e.g. "Drag and drop an image, or click to browse"). */
    label: string
    /** Format or size hint below the CTA. Hidden when unset. */
    hint?: string
    /** Override the default {@link ImageIcon}. Pass a component reference, not JSX. */
    icon?: IconComponent
    /**
     * Pins the drag-active visual state from outside. Real drag-and-drop cannot
     * be triggered programmatically, so Storybook has no other way to show this
     * state. Unset, the composite tracks it internally via `useDropzone`; set, it
     * overrides the internal state.
     */
    isDragActive?: boolean
    /**
     * When true, keeps the dashed frame real and shimmers `label` / `hint` via
     * `Typography` (COMPOSITE-10). Icon is hidden while loading. @default false
     */
    isSkeleton?: boolean
}

/**
 * ImageDropzone ΓÇö single-image drop target. Accepts png/jpeg/webp/gif up to 5 MB
 * by drop or click. Owns drag-active chrome and the icon / label / hint column.
 * Presentational: the caller handles the file.
 *
 * @param props - {@link ImageDropzoneProps}
 */
export const ImageDropzone = ({
    onFile,
    label,
    hint,
    icon: Icon,
    isDragActive: isDragActiveProp,
    isSkeleton = false,
}: ImageDropzoneProps) => {
    const { getRootProps, getInputProps, isDragActive: isDragActiveInternal } = useDropzone({
        accept: ACCEPT,
        maxSize: MAX_SIZE,
        multiple: false,
        onDrop: (accepted) => {
            const next = accepted[0]
            if (next) {
                onFile(next)
            }
        },
    })
    const isDragActive = isDragActiveProp ?? isDragActiveInternal

    return (
        <div
            {...(isSkeleton ? {} : getRootProps())}
            data-tier="composite"
            data-component="ImageDropzone"
            className={cn(
                "flex flex-col items-center gap-2 rounded-2xl border border-dashed border-separator px-6 py-8 text-center",
                !isSkeleton && "cursor-pointer transition-colors hover:border-accent",
                !isSkeleton && isDragActive && "border-solid border-accent bg-accent-soft",
            )}
        >
            {isSkeleton ? null : <input {...getInputProps()} />}
            {isSkeleton ? null : (
                <span
                    aria-hidden
                    className={cn("text-muted [&_svg]:size-8", isDragActive && "text-accent-soft-foreground")}
                >
                    {Icon ? <Icon /> : <ImageIcon focusable="false" />}
                </span>
            )}
            {isSkeleton ? (
                <Typography size="sm" weight="medium" isSkeleton />
            ) : (
                <span
                    className={cn(
                        "text-sm font-medium text-center",
                        isDragActive ? "text-accent-soft-foreground" : "text-foreground",
                    )}
                >
                    {label}
                </span>
            )}
            {hint != null && hint !== "" ? (
                isSkeleton ? (
                    <Typography size="xs" isSkeleton />
                ) : (
                    <span className="text-xs font-normal text-muted text-center">
                        {hint}
                    </span>
                )
            ) : null}
        </div>
    )
}

/** Source-level tier metadata. */
export const meta = { tier: "composite", name: "ImageDropzone" } as const

import type { ReactNode } from "react"
import { Label, Skeleton as HeroSkeleton, cn } from "@heroui/react"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"

/**
 * `FieldFrame` ΓÇö the label / hint / control / error scaffold every form atom
 * composes so the atom itself is the full field.
 *
 * Composite form helper: label / hint / control / error scaffold.
 * Owns the vertical rhythm (`flex flex-col`, a fixed `gap-3` ΓÇö the label rule,
 * see `FIELD_SEAM`): label on top, hint below the label, control, error line
 * last ΓÇö and mirrors the exact shape when `isSkeleton`.
 *
 * "Bare" mode: when there is no label/hint/errorMessage/required (and not
 * skeleton), FieldFrame renders `children` directly with zero wrapper, so the
 * atom can still be used as a bare cell nested inside something else.
 */
export interface FieldFrameProps {
    /** Label above the control (`text-sm font-medium`). Omit ΓåÆ no label. */
    label?: ReactNode
    /** Description below the label (`text-xs text-muted`) ΓÇö ALWAYS shown (unlike errorMessage). */
    hint?: ReactNode
    /** Error line below the control (`text-sm text-danger`) ΓÇö set ΓåÆ field invalid. */
    errorMessage?: ReactNode
    /** Adds a `*` mark (text-danger) after the label. */
    isRequired?: boolean
    /** Dims the label (locking the control itself is the atom's job). */
    isDisabled?: boolean
    /** Loading mirror: a label-width skeleton over a control-skeleton, keeping the same column. */
    isSkeleton?: boolean
    /** Control-shaped skeleton for `isSkeleton` (the atom passes its own box). */
    skeletonControl?: ReactNode
    /**
     * The real control (an already-wrapped HeroUI cell). `FieldFrame` is a
     * wrapping frame that must accept the calling atom's arbitrary control
     * as-is (Input/Select/Choice/ΓÇª) ΓÇö it can't be swapped for a data prop,
     * since the control isn't "content" but a whole component tree.
     */
    children?: ReactNode
    /** The control's `id` so the label's `htmlFor` points correctly ΓÇö the atom passes the same id down to the control. */
    id?: string
    /** Where this sits inside its parent (the outer column). Everything about appearance is a prop of its own. */
    classNames?: Array<AllowedClassName>
}

/**
 * Accessible NAME for the control: when `label` is a string, use it directly
 * (guarantees the control always has a readable name ΓÇö even a compound control
 * like Number/Date/Otp that can't wire up `htmlFor`), otherwise falls back to
 * `fallback` (ariaLabel/placeholder). Avoids the a11y gap of an "unnamed control"
 * when a field has a label that can't be associated.
 */
export const fieldName = (label: ReactNode, fallback?: string): string | undefined =>
    typeof label === "string" ? label : fallback

/**
 * The seam between a label and the control it names is step 4 (`gap-3`, 12px) ΓÇö a label names its
 * subject across a change of register, and `principles/gap.md`'s label rule sits that boundary at
 * step 4. It is fixed, not a prop: the old `tight`/`related` choice let one field breathe at a
 * different rhythm than the next for no reason a reader could name, which is the ambiguity the
 * numeric scale exists to end. Every field in the system now stacks at the same seam.
 */
const FIELD_SEAM = "gap-3"

/** Label + `*` mark when required. */
const withRequired = (label: ReactNode, isRequired?: boolean) =>
    isRequired ? (
        <>
            {label} <span className="text-danger">*</span>
        </>
    ) : (
        label
    )

/**
 * `FieldFrame` ΓÇö label/hint/control/error column shared by every form atom.
 * @param props - {@link FieldFrameProps}
 */
const FieldFrameBase = ({
    label,
    hint,
    errorMessage,
    isRequired,
    isDisabled,
    isSkeleton,
    skeletonControl,
    children,
    id,
    classNames,
}: FieldFrameProps) => {
    const hasFrame = label != null || hint != null || errorMessage != null

    // ΓöÇΓöÇ Loading mirror ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    if (isSkeleton) {
        // Bare skeleton (no label frame) ΓåÆ just the control skeleton box (badges Skeleton itself).
        if (!hasFrame && label == null) {
            return <>{skeletonControl}</>
        }
        return (
            <div data-tier="composite" data-component="FieldFrame" data-principle="label-field" className={cn("flex flex-col", FIELD_SEAM, classNames)}>
                {label != null ? (
                    // label-bar look), not the slot word "Label" it stands in for.
                    <HeroSkeleton className="h-4 w-1/3 rounded-md" />
                ) : null}
                {skeletonControl}
            </div>
        )
    }

    // ΓöÇΓöÇ "Bare" ΓÇö no frame ΓåÆ renders the control directly ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    if (!hasFrame) {
        return <>{children}</>
    }

    // ΓöÇΓöÇ Full field ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
    return (
        <div data-tier="composite" data-component="FieldFrame" className={cn("flex flex-col", FIELD_SEAM, classNames)}>
            {label != null ? (
                <Label htmlFor={id} isDisabled={isDisabled} className="text-sm font-medium">
                    {withRequired(label, isRequired)}
                </Label>
            ) : null}

            {hint != null ? (
                <p className="text-muted text-xs">
                    {hint}
                </p>
            ) : null}

            {children}

            {errorMessage != null ? (
                <p className="text-danger text-sm">
                    {errorMessage}
                </p>
            ) : null}
        </div>
    )
}

/** `FieldFrame` ΓÇö label/hint/control/error scaffold. */
export { FieldFrameBase as FieldFrame }

export const meta = { tier: "composite", name: "FieldFrame" } as const

