// .BottomBar ΓÇö the viewport-pinned action bar (was `StickyBottomBar`)
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/** Props for {@link PageBottomBar}. */
export interface PageBottomBarProps {
    /**
     * Leading content of the bar ΓÇö typically a price ΓÇö as a COMPONENT
     * reference (COMPOSITE-8): the frame calls it itself so it can forward
     * `isSkeleton`.
     */
    body?: ComponentTypeWithSkeleton
    /**
     * Trailing control(s) ΓÇö the primary CTA ΓÇö as a COMPONENT reference. When
     * BOTH `body` and `actions` are given the frame lays out the row itself
     * (`justify-between`, `shrink-0` on the actions) so callers stop
     * hand-rolling that flex row.
     */
    actions?: ComponentTypeWithSkeleton
    /** Shorthand for {@link PageBottomBarProps.body} ΓÇö same component-reference contract. */
    /**
     * `true` ΓåÆ forwarded into whichever of `body`/`actions` renders, so a bar
     * whose price/CTA is not known yet (e.g. still loading enrollment status)
     * can shimmer instead of showing stale content.
     */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable ΓÇö it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * A fixed bottom action bar pinned to the viewport edge ΓÇö owns the chrome
 * (fixed position, top divider, surface background, safe padding) so features
 * just drop a price + CTA inside. Typically `@app-md:hidden` for a mobile sticky
 * enroll/checkout bar.
 *
 * A bar is a horizontal row, so its named slots are `body` (leading) +
 * `actions` (trailing) rather than the vertical `header`/`body`/`footer` trio.
 * With only one of them the content renders RAW, so a full-width button or a
 * two-button decision row keeps its own sizing (`flex-1`, `w-full`).
 *
 * @param props - {@link PageBottomBarProps}
 */
const BottomBar = ({
    body,
    actions,
    isSkeleton = false,
    classNames}: PageBottomBarProps) => {
    const Main = body
    const Actions = actions
    const chrome = "fixed bottom-0 left-0 right-[var(--app-rail-w,0px)] z-40 border-t border-separator bg-background px-6 py-3"

    // Only ONE side supplied ΓåÆ render it raw: the caller's own width strategy
    // (`w-full` CTA, two `flex-1` buttons) must not be boxed by a shrink-0 wrapper.
    if (Main == null || Actions == null) {
        const Only = Main ?? Actions
        return (
            <div className={cn(chrome, classNames)} data-tier="composite" data-component="PageBottomBar">
                <div>{Only ? <Only isSkeleton={isSkeleton} /> : null}</div>
            </div>
        )
    }

    return (
        <div className={cn(chrome, classNames)} data-tier="composite" data-component="PageBottomBar">
            <StackH
                align="center"
                justify="between"
                gap={4}
                principle="content-row"
                explain="Keeps primary content and trailing meta on one baseline so the meta does not drop under the title."
                items={[
                    () => <div className="min-w-0"><Main isSkeleton={isSkeleton} /></div>,
                    () => <div className="shrink-0"><Actions isSkeleton={isSkeleton} /></div>,
                ]}
            />
        </div>
    )
}

/**
 * Page chrome members ΓÇö a route imports these by name:
 *
 * | Export | Content channel |
 * |---|---|
 * | `PageHeader` | `breadcrumb`/`title`/`description`/`actions`/`meta` (no children) |
 * | `PageBottomBar` | `body`/`actions` slots |
 *
 * `.Container` moved to `Container` (`@/components/frames/Container/Container`)
 * on 2026-07-26 ΓÇö see the history note at the top of this file.
 */
export { Header as PageHeader, BottomBar as PageBottomBar }

import type { ReactNode } from "react"
import { cn } from "@heroui/react"
import type { AllowedClassName } from "@/components/atoms/_allowed-class-name"
import { Typography, type TypographySize } from "@/components/atoms/text/Typography"
import { GAP_CLASS, type AllowedGap } from "@/components/frames/_spacing"
import { StackH, StackV } from "@/components/frames/Stack"
import type { ComponentTypeWithSkeleton } from "@/components/frames/_slot"

/**
 * ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
 * COMPOSITE TIER (┬º13) ΓÇö `Section.*`, the frame of a REGION inside a page.
 *
 * A section is the region between a page and a card: a titled band of a route
 * ("My courses", "Recent activity") that owns NO chrome of its own ΓÇö no
 * surface fill, no border, no radius, no padding. It only stacks a header, a
 * body and an optional footer at ONE rhythm (┬º10).
 *
 * ΓÜá∩╕Å NOT `SectionCard` (design tier, `blocks/cards/SectionCard`): that one IS a
 * card ΓÇö HeroUI `Card` chrome (border + radius + padding), an `accent` skin, a
 * `withVerdict` DATA band and its own `isSkeleton` mirror. `SectionCard` is the
 * SURFACE a section's body may sit ON; `Section` is the bare frame AROUND it.
 * Rule of thumb: needs a bounded surface ΓçÆ `SectionCard`/`SurfaceCard.*`; only
 * needs "title + content in one vertical rhythm" ΓçÆ `Section.*`.
 *
 * ΓÜá∩╕Å NOT `PageHeader` either: that is the chrome of a whole ROUTE (breadcrumb +
 * H3 title + meta strip), ONE per page. `SectionHeader` is the header of a
 * region INSIDE that page, many per page, and scales down via `level`.
 *
 * KHUNG API LAW (┬º13b):
 * - `.Base` is a WRAPPER frame ΓåÆ named slots `header`/`body`/`footer` are the
 *   main road, each a COMPONENT reference (COMPOSITE-8) this frame calls
 *   itself so `isSkeleton` can reach inside it.
 * - `.Header` is NOT a generic wrapper ΓåÆ it owns semantic slots
 *   (`eyebrow`/`title`/`description`/`action`) and takes no `children`.
 * - No repeating list here, so no `items` member (┬º13b list clause N/A).
 * - Namespace only ΓÇö no bare component export.
 *
 * ┬º10: the vertical rhythm is a TYPED token ({@link AllowedGap}), not a free number ΓÇö
 * the frame cannot be asked for an off-scale step.
 * ┬º13c: `title`/`description`/`eyebrow` are plain text ΓÇö the frame wraps them in the
 * `Typography.*` ATOM itself, never a hand-rolled `<p>` (COMPOSITE-8); `action` takes
 * a COMPONENT reference composing a `Button.*` atom from the caller (the frame stays
 * feature-less ΓÇö it never decides WHAT the action is).
 * ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
 */

/** Source-level tier metadata ΓÇö see `.claude/design/storybook/architecture/elements/*.md`. */
export const meta = { tier: "composite", name: "Section" } as const

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// Shared scale
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
// .Header ΓÇö eyebrow ┬╖ title ┬╖ description ┬╖ action
// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

/**
 * Heading rank of a section header ΓÇö picks the `Typography.*` member for every
 * line at once (title + description + eyebrow move together, so a header never
 * mixes scales by hand).
 *
 * `1` = the biggest band of a page ┬╖ `2` (default) = a normal section ┬╖
 * `3` = a sub-section nested under another header.
 */
export type SectionLevel = 1 | 2 | 3

/** level ΓåÆ the text size each line uses. A DATA table ΓÇö the call-site never chooses it by hand. */
const TITLE_SIZE: Record<SectionLevel, TypographySize> = { 1: "lg", 2: "base", 3: "sm" }
const DESCRIPTION_SIZE: Record<SectionLevel, TypographySize> = { 1: "sm", 2: "sm", 3: "xs" }
const EYEBROW_SIZE: Record<SectionLevel, TypographySize> = { 1: "sm", 2: "xs", 3: "xs" }
/** ┬º9b: the two top ranks read as headings (bold); the sub-section rank is only emphasized (medium). */
const TITLE_WEIGHT: Record<SectionLevel, "bold" | "medium"> = {
    1: "bold",
    2: "bold",
    3: "medium"}

/** Props for {@link SectionHeader}. */
export interface SectionHeaderProps {
    /** The region's title. The frame wraps it in `Typography` itself (COMPOSITE-8). */
    title: string
    /** Supporting line under the title, muted. Omit when the title says it all. The frame wraps it in `Typography` itself (COMPOSITE-8). */
    description?: string
    /** Muted kicker ABOVE the title ΓÇö context, not a second title (e.g. a course name). The frame wraps it in `Typography` itself (COMPOSITE-8). */
    eyebrow?: string
    /**
     * Right-aligned control slot ΓÇö a COMPONENT reference (COMPOSITE-8) the frame
     * calls itself, usually rendering a `Button.*` atom node ("View all",
     * "Manage"). Rendered `shrink-0` so it never squeezes the title column. The
     * frame never decides WHAT the action does (that would be a feature, ┬º13).
     */
    action?: ComponentTypeWithSkeleton
    /** Heading rank ΓåÆ the text scale of every line. Default `2`. */
    level?: SectionLevel
    /**
     * `true` ΓåÆ `title`/`description`/`eyebrow` switch to shimmer, and `action`
     * (if any) is CALLED with `isSkeleton` too (COMPOSITE-8 ΓÇö `action` is a
     * component reference this frame calls itself, so the flag reaches inside
     * it the same way it reaches the text lines).
     */
    isSkeleton?: boolean
    /**
     * Where this sits inside its parent. Appearance is not passable ΓÇö it is already a prop.
     */
    classNames?: Array<AllowedClassName>
}

/**
 * The header of a section: an optional eyebrow + a title + an optional
 * description stacked on the left, an optional action pinned right.
 *
 * Carries no surface of its own ΓÇö it sits directly on the page background (or
 * inside whatever surface the caller already opened).
 *
 * @param props - {@link SectionHeaderProps}
 */
const Header = ({
    title,
    description,
    eyebrow,
    action: Action,
    level = 2,
    isSkeleton = false,
    classNames}: SectionHeaderProps) => {
    const titleSize = TITLE_SIZE[level]
    const descriptionSize = DESCRIPTION_SIZE[level]
    const eyebrowSize = EYEBROW_SIZE[level]
    // eyebrow Γåö title Γåö description are ONE text unit ΓåÆ tight gap={2} (┬º10b
    // "inside a lower-tier component"), not the grouped gap={4} used BETWEEN regions.
    const titleBlock = (
        <>
            {eyebrow != null ? (
                <span className="min-w-0">
                    <Typography size={eyebrowSize} text={eyebrow} color="muted" truncate isSkeleton={isSkeleton} />
                </span>
            ) : null}
            <span className="min-w-0">
                <Typography size={titleSize} text={title} weight={TITLE_WEIGHT[level]} isSkeleton={isSkeleton} />
            </span>
            {description != null ? (
                <span className="min-w-0">
                    <Typography size={descriptionSize} text={description} color="muted" isSkeleton={isSkeleton} />
                </span>
            ) : null}
        </>
    )
    return (
        // align="start": a 2-line title block keeps the action anchored at the top.
        <StackH
            align="start"
            justify="between"
            gap={4}
            classNames={classNames}
            isSkeleton={isSkeleton}
            items={[
                () => <StackV gap={2} principle="title-subtitle" classNames={["min-w-0"]} isSkeleton={isSkeleton} items={[() => titleBlock]} explain="Title over supporting line ΓÇö not label-field, because neither line is a form control label."/>,
                ...(Action != null ? [() => (
                    <div className="shrink-0"><Action isSkeleton={isSkeleton} /></div>
                )] : []),
            ]}
        />
    )
}

